[1666] = "Вычисление: %s",
-- 55a7b6a1 English: Fields UI and Help offer an explicit Preview of the current callback. Preview
--     uses detached sample values and the normal field or help renderer. It does not save,
--     register, validate or evaluate the condition. Closing it releases its controls and returns to
--     the source draft. Check syntax never runs a callback.
[1667] = "«Интерфейс полей» и «Справка» предлагают явный предпросмотр текущего обратного вызова. Предпросмотр использует отдельные образцы значений и обычный отрисовщик полей или справки. Он не сохраняет, не регистрирует, не проверяет и не вычисляет условие. Закрытие освобождает его элементы и возвращает к черновику исходного кода. «Проверить синтаксис» никогда не запускает обратный вызов.",
-- 106d8f1b English: Evaluate and Validate offer Check with the same Fields UI and detached sample
--     values. Check runs validation first, then evaluates only valid values. Results show true,
--     false or an unavailable reason. Live is opt-in and checks at most twice per second while this
--     panel is shown; closing stops it. Test values are saved separately and never enter condition
--     exports or rotation edits. Source changes run no callbacks unless you check again or enable
--     Live.
[1668] = "«Вычисление» и «Проверка» предлагают «Проверить» с тем же интерфейсом полей и отдельными образцами значений. Сначала выполняется проверка, затем вычисляются только корректные значения. Результат — истина, ложь или причина недоступности. Режим «В реальном времени» включается вручную и проверяет не чаще двух раз в секунду, пока эта панель показана; закрытие останавливает его. Тестовые значения хранятся отдельно и никогда не попадают в экспорт условий или правки ротаций. Изменения исходного кода не запускают обратные вызовы, пока вы снова не проверите или не включите «В реальном времени».",
-- 5d331ffe English: Functions reference
[1669] = "Справочник функций",
-- 64334745 English: The Functions page documents public helpers and their typed arguments, return
--     values and source. Context completion and hover use that reference; Ctrl-click a known helper
--     to open its source. Use explicit binding aliases for reusable custom helpers.
[1670] = "Страница «Функции» документирует общедоступных помощников, их типизированные аргументы, возвращаемые значения и исходный код. Контекстное автодополнение и всплывающие подсказки используют этот справочник; щелчок с Ctrl по известному помощнику открывает его код. Для многоразовых пользовательских помощников используйте явные псевдонимы привязок.",
-- 8f344bfe English: The imported definition type does not match this editor.
[1671] = "Тип импортированного определения не соответствует этому редактору.",
-- 91fe2974 English: Test values changed. Check again to refresh the result.
[1672] = "Тестовые значения изменены. Проверьте снова, чтобы обновить результат.",
-- 4087dcf1 English: Complete the highlighted test inputs before checking.
[1673] = "Перед проверкой заполните выделенные тестовые поля.",
-- 532eaabd English: Test
[1674] = "Тест",
-- e031e0df English: Run test
[1675] = "Запустить тест",
-- 312acdf1 English: Test condition
[1676] = "Тест условия",
-- 34fb96f5 English: Debugger output
[1677] = "Вывод отладчика",
-- e376955f English: Set test values in Test before debugging Evaluate.
[1678] = "Перед отладкой «Вычисления» задайте тестовые значения в «Тесте».",
-- 427ea36c English: Debugger output uses a detached sample and the normal field or help container.
[1679] = "Вывод отладчика использует отдельный образец и обычный контейнер полей или справки.",
-- af624aba English: Choose test values in Fields UI, then Run test to validate and evaluate. Help
--     is shown below the fields. Opening Test does not evaluate defaults. Live is opt-in.
[1680] = "Выберите тестовые значения в «Интерфейсе полей», затем нажмите «Запустить тест» для проверки и вычисления. Справка показана под полями. Открытие «Теста» не вычисляет значения по умолчанию. Режим «В реальном времени» включается вручную.",
-- fba588f1 English: Test opens one condition-level dialog from any callback tab. It renders Fields
--     UI and Help together with detached values. Choose the fields and Run test to validate, then
--     evaluate only valid values. Opening the dialog does not evaluate defaults. Live is opt-in and
--     stops when the dialog closes. Committed test values are available to the debugger and stay
--     separate from source, exports and rotation edits. Check syntax never runs a callback.
[1681] = "«Тест» открывает одно окно уровня условия с любой вкладки обратного вызова. В нём вместе показаны интерфейс полей и справка с отдельными значениями. Выберите поля и нажмите «Запустить тест» для проверки, после чего вычисляются только корректные значения. Открытие окна не вычисляет значения по умолчанию. Режим «В реальном времени» включается вручную и останавливается при закрытии окна. Подтверждённые тестовые значения доступны отладчику и хранятся отдельно от исходного кода, экспорта и правок ротации. «Проверить синтаксис» никогда не запускает обратный вызов.",
-- deba1c35 English: Nullable
[1682] = "Допускает nil",
-- fbf338e4 English: Add return value
[1683] = "Добавить возвращаемое значение",
-- c75ed23e English: Lua returns multiple values in order. Each row documents one result.
[1684] = "Lua возвращает несколько значений по порядку. Каждая строка документирует один результат.",
-- f968686c English: Expand code editor
[1685] = "Развернуть редактор кода",
-- cc81db61 English: Restore code editor
[1686] = "Восстановить редактор кода",
-- cb050073 English: Choose a source helper and the local name used to call it in this Lua body.
--     Renaming the local name does not rewrite code. Source modules distinguish helpers with the
--     same name.
[1687] = "Выберите помощник-источник и локальное имя, под которым он вызывается в этом теле Lua. Переименование локального имени не переписывает код. Модули-источники различают помощников с одинаковыми именами.",
-- cfaec007 English: Local name in code
[1688] = "Локальное имя в коде",
-- d076565e English: Source helper
[1689] = "Помощник-источник",
-- b49f05b5 English: Function names use letters, numbers and underscores, beginning with a letter or
--     underscore. Names suggest the local binding used to call them; registry identifiers stay
--     stable.
[1690] = "Имена функций состоят из латинских букв, цифр и подчёркиваний и начинаются с буквы или подчёркивания. Имена предлагают локальную привязку для вызова; идентификаторы в реестре остаются постоянными.",
-- b545dd16 English: This cannot be undone.
[1691] = "Это нельзя отменить.",
-- f07f87d9 English: Delete this announcement?
[1692] = "Удалить это оповещение?",
-- da985348 English: Type: %s
[1693] = "Тип: %s",
-- 78a0b485 English: Supported unit-token to localized unit-name lookup. Use value.unit as a key;
--     for example addon.units[value.unit]. Available tokens vary by client.
[1694] = "Таблица соответствия поддерживаемых токенов юнитов и их локализованных названий. Используйте value.unit как ключ, например addon.units[value.unit]. Доступные токены зависят от клиента.",
-- b2a921f3 English: Supported unit-token to localized possessive unit-name lookup, such as your
--     target.
[1695] = "Таблица соответствия поддерживаемых токенов юнитов и их локализованных притяжательных названий, например «вашей цели».",
-- 7e1dc663 English: Rotation Master client compatibility adapter. Its methods return ordinary
--     readable results or nil with a reason when an observation is unavailable. Use a colon call,
--     or pass addon.Platform explicitly as self with a dot reference.
[1696] = "Адаптер совместимости клиентов Rotation Master. Его методы возвращают обычные читаемые результаты или nil с причиной, если наблюдение недоступно. Вызывайте через двоеточие или явно передавайте addon.Platform как self при обращении через точку.",
-- bbc0cdbf English: Rotation Master spell catalog for resolving client-specific spell IDs, ranks,
--     names, icons and links.
[1697] = "Каталог заклинаний Rotation Master для определения зависящих от клиента ID заклинаний, рангов, названий, иконок и ссылок.",
-- 18123a69 English: Utility functions explicitly bound to this condition or function. Choose a
--     completion to bind an available custom function before inserting its reference.
[1698] = "Вспомогательные функции, явно привязанные к этому условию или функции. Выберите вариант автодополнения, чтобы привязать доступную пользовательскую функцию перед вставкой ссылки на неё.",
-- 16356339 English: Rotation Master custom function
[1699] = "Пользовательская функция Rotation Master",
-- 902c5c44 English: Rotation Master built-in function
[1700] = "Встроенная функция Rotation Master",
-- 0443c4a6 English: Rotation Master value
[1701] = "Значение Rotation Master",
-- 1a845fe0 English: Global function (documentation unavailable on this client)
[1702] = "Глобальная функция (документация недоступна на этом клиенте)",
-- 6912e131 English: This client does not provide signature documentation for this function. No
--     arguments or return types have been inferred.
[1703] = "Этот клиент не предоставляет документацию сигнатуры для этой функции. Аргументы и типы возвращаемых значений не выводились.",
-- 90092e5f English: Invoke
[1704] = "Вызов",
-- cb214676 English: Functions are shared across profiles after Apply. Call custom utilities as
--     functions.name(...); accepting completion adds the dependency binding. Typed calls need a
--     binding under Function bindings. Built In examples show dot or colon explicitly.
[1705] = "После применения функции общие для всех профилей. Вызывайте пользовательские утилиты как functions.name(...); принятие автодополнения добавляет привязку зависимости. Для набранных вручную вызовов нужна привязка в «Привязках функций». Примеры встроенных функций явно показывают точку или двоеточие.",
-- d03262ba English: Show line numbers
[1706] = "Показывать номера строк",
-- f12fff00 English: Line-number visibility applies to every condition and function code editor.
[1707] = "Видимость номеров строк применяется ко всем редакторам кода условий и функций.",
-- 596578e6 English: Call a saved custom utility as functions.name(...). Accepting a completion
--     attaches its stable dependency binding; for a typed call, choose its helper under Function
--     bindings. Existing direct aliases still work. The Invoke example shows required addon dot or
--     colon syntax for Built In functions. Renaming an alias does not rewrite source. Missing,
--     disabled or invalid dependencies keep consumers unavailable.
[1708] = "Вызывайте сохранённую пользовательскую утилиту как functions.name(...). Принятие автодополнения добавляет её постоянную привязку зависимости; для набранного вручную вызова выберите помощника в «Привязках функций». Существующие прямые псевдонимы по-прежнему работают. Пример «Вызов» показывает обязательный синтаксис через точку или двоеточие для встроенных функций. Переименование псевдонима не переписывает исходный код. Отсутствующие, отключённые или некорректные зависимости оставляют использующий их код недоступным.",
-- 38416c88 English: Choose the editor for custom Lua conditions and functions. Show line numbers
--     applies across code editors. Built In syntax highlighting and Plain text work without another
--     addon. Automatic selects a connected provider or falls back safely. Apply saves settings;
--     editor changes take effect on reopening, and line-number visibility updates open editors.
--     LuaWorkbench and WowLua loading status is shown separately from integration availability.
[1709] = "Выберите редактор для пользовательских условий и функций Lua. «Показывать номера строк» действует во всех редакторах кода. Встроенная подсветка синтаксиса и простой текст работают без других аддонов. «Автоматически» выбирает подключённого поставщика или безопасно возвращается к встроенному. «Применить» сохраняет настройки; смена редактора вступает в силу при повторном открытии, а видимость номеров строк обновляется в открытых редакторах. Состояние загрузки LuaWorkbench и WowLua показывается отдельно от доступности интеграции.",
-- 50c3cb6e English: All namespaces
[1710] = "Все пространства имён",
-- 5605815a English: Call a utility as namespace.name(...). Built In namespaces follow source files;
--     custom functions choose their Namespace. Accepting a completion attaches its stable
--     dependency binding; for a typed call, add its qualified name under Function bindings.
--     Namespaces do not supply self: the Invoke example includes a method receiver explicitly, and
--     Existing API preserves its original dot or colon spelling. Existing aliases still work.
--     Renaming a function or namespace does not rewrite existing code or bindings. Missing,
--     disabled or invalid dependencies keep consumers unavailable.
[1711] = "Вызывайте утилиту как namespace.name(...). Встроенные пространства имён соответствуют файлам исходного кода; пользовательские функции выбирают своё пространство имён. Принятие автодополнения добавляет постоянную привязку зависимости; для набранного вручную вызова добавьте его полное имя в «Привязки функций». Пространства имён не передают self: пример «Вызов» явно включает получателя метода, а «Существующий API» сохраняет исходное написание через точку или двоеточие. Существующие псевдонимы по-прежнему работают. Переименование функции или пространства имён не переписывает существующий код и привязки. Отсутствующие, отключённые или некорректные зависимости оставляют использующий их код недоступным.",
-- 66506282 English: Choose a source helper and its name in this Lua body, such as custom.ready or
--     utils.getCached. Namespaces are private to this callback. Renaming a binding does not rewrite
--     code.
[1712] = "Выберите помощник-источник и его имя в этом теле Lua, например custom.ready или utils.getCached. Пространства имён закрыты для этого обратного вызова. Переименование привязки не переписывает код.",
-- 5226404c English: Existing API
[1713] = "Существующий API",
-- e572edc2 English: Name in code
[1714] = "Имя в коде",
-- c4e4e7ab English: Namespace
[1715] = "Пространство имён",
-- c6d86222 English: Namespaces group functions; they do not supply a receiver. Accept a completion
--     to bind the shown dotted call. For a typed call, add the same qualified name under Function
--     bindings. Method examples include the required receiver explicitly. Functions are shared
--     across profiles after Apply.
[1716] = "Пространства имён группируют функции; они не передают получателя. Примите автодополнение, чтобы привязать показанный вызов через точку. Для набранного вручную вызова добавьте то же полное имя в «Привязки функций». Примеры методов явно включают обязательного получателя. После применения функции общие для всех профилей.",
-- 76209725 English: Private utility-function namespace. It contains only explicit bindings for this
--     callback.
[1717] = "Закрытое пространство имён вспомогательных функций. Содержит только явные привязки для этого обратного вызова.",
-- 481da3a7 English: Argument
[1718] = "Аргумент",
-- e0836fce English: Bindings (%d)
[1719] = "Привязки (%d)",
-- 6ecb5a70 English: Call a utility as namespace.name(...). Built In namespaces follow source files;
--     custom functions choose their Namespace. Accepting a completion attaches its stable
--     dependency binding; for a typed call, add its qualified name under Function bindings.
--     Namespaces do not supply self. Pass a method receiver explicitly in a namespaced dot call;
--     object:method(x) is Lua shorthand for object.method(object, x). Existing addon APIs remain
--     compatible with saved definitions. Existing aliases still work. Renaming a function or
--     namespace does not rewrite existing code or bindings. Missing, disabled or invalid
--     dependencies keep consumers unavailable.
[1720] = "Вызывайте утилиту как namespace.name(...). Встроенные пространства имён соответствуют файлам исходного кода; пользовательские функции выбирают своё пространство имён. Принятие автодополнения добавляет постоянную привязку зависимости; для набранного вручную вызова добавьте его полное имя в «Привязки функций». Пространства имён не передают self. В вызове через точку из пространства имён передавайте получателя метода явно; object:method(x) — сокращение Lua для object.method(object, x). Существующие API аддона остаются совместимыми с сохранёнными определениями. Существующие псевдонимы по-прежнему работают. Переименование функции или пространства имён не переписывает существующий код и привязки. Отсутствующие, отключённые или некорректные зависимости оставляют использующий их код недоступным.",
-- d35a9985 English: Changing argument or return order can break existing callers. Rotation Master
--     will not rewrite their Lua code. Continue?
[1721] = "Изменение порядка аргументов или возвращаемых значений может сломать существующие вызовы. Rotation Master не будет переписывать их код Lua. Продолжить?",
-- 2199cecc English: Click an Arguments or Returns heading to collapse or expand it. + Argument and
--     + Return append when clicked, or insert at a highlighted gap when dragged. Drag a row or use
--     Up / Down to reorder; Ctrl-drag carries following rows. The trash can removes a row. Type and
--     Nullable document accepted values; Description explains each input or result. Lua can return
--     several ordered results. Reordering a saved function warns because positional callers may
--     need changes; RM does not rewrite call sites.
[1722] = "Нажмите на заголовок «Аргументы» или «Возвращаемые значения», чтобы свернуть или развернуть его. «+ Аргумент» и «+ Возврат» добавляют в конец при нажатии или вставляют в выделенный промежуток при перетаскивании. Перетаскивайте строку или используйте «Вверх» / «Вниз» для изменения порядка; с Ctrl переносятся и следующие строки. Корзина удаляет строку. «Тип» и «Допускает nil» документируют допустимые значения; «Описание» поясняет каждый вход или результат. Lua может возвращать несколько упорядоченных результатов. При изменении порядка у сохранённой функции появляется предупреждение, так как позиционные вызовы могут потребовать правки; RM не переписывает места вызова.",
-- 6b0143d0 English: Return
[1723] = "Возврат",
-- 2584fdfb English: Changing argument order can break existing callers. Rotation Master will not
--     rewrite their Lua code. Continue?
[1724] = "Изменение порядка аргументов может сломать существующие вызовы. Rotation Master не будет переписывать их код Lua. Продолжить?",
-- 79fbb27b English: Changing return documentation order does not rewrite return statements or
--     existing callers. Review the Lua body and callers for the new order. Continue?
[1725] = "Изменение порядка в документации возвращаемых значений не переписывает операторы return и существующие вызовы. Проверьте тело Lua и вызовы на соответствие новому порядку. Продолжить?",
-- 2266dd0b English: Card controls
[1726] = "Элементы карточки",
-- 1f03f52f English: Describe this value for function documentation, completion and hover help.
--     Changes remain in the draft until Apply.
[1727] = "Опишите это значение для документации функции, автодополнения и всплывающих подсказок. Изменения остаются в черновике до нажатия «Применить».",
-- 9513dcfb English: Drag a card to reorder arguments; Ctrl-drag includes following arguments. Up
--     and down move one position. Duplicate copies the argument with a unique name; the trash can
--     removes it. Reordering a saved function requires confirmation because existing callers are
--     not rewritten.
[1728] = "Перетаскивайте карточку, чтобы менять порядок аргументов; с Ctrl переносятся и следующие аргументы. «Вверх» и «Вниз» сдвигают на одну позицию. «Дублировать» копирует аргумент с уникальным именем; корзина удаляет его. Изменение порядка у сохранённой функции требует подтверждения, так как существующие вызовы не переписываются.",
-- 33f24b5d English: Drag a card to reorder return documentation; Ctrl-drag includes following
--     returns. Up and down move one position. Duplicate copies the documented return value; the
--     trash can removes it. Return order in this list does not rewrite return statements or
--     callers.
[1729] = "Перетаскивайте карточку, чтобы менять порядок документации возвращаемых значений; с Ctrl переносятся и следующие. «Вверх» и «Вниз» сдвигают на одну позицию. «Дублировать» копирует описанное возвращаемое значение; корзина удаляет его. Порядок в этом списке не переписывает операторы return и вызовы.",
-- 74057930 English: Rendered output appears here when the callback runs or steps through widget
--     creation.
[1730] = "Здесь появится отрисованный результат, когда обратный вызов выполнится или пошагово пройдёт создание виджета.",
-- 47b50257 English: Set values in Test before running or debugging this condition.
[1731] = "Перед запуском или отладкой этого условия задайте значения в «Тесте».",
-- 96aa8cc3 English: The argument name is the local parameter available in the Lua body. Use a valid
--     Lua identifier. Renaming this documentation does not rewrite references in the code.
[1732] = "Имя аргумента — локальный параметр, доступный в теле Lua. Используйте допустимый идентификатор Lua. Переименование в документации не переписывает ссылки в коде.",
-- 438e9a47 English: Type and Nullable describe the values accepted or returned by this function.
--     They document the contract; they do not rewrite or validate values in the Lua body.
[1733] = "«Тип» и «Допускает nil» описывают значения, которые функция принимает или возвращает. Они документируют контракт и не переписывают и не проверяют значения в теле Lua.",
-- 42e8bcf1 English: Debuffs
[1734] = "Отриц. эффекты",
-- e89b30aa English: Resources
[1735] = "Ресурсы",
-- 8f0d1b30 English: Pet
[1736] = "Питомец",
-- 7c400199 English: Logic
[1737] = "Логика",
-- 9e471951 English: Environment
[1738] = "Окружение",
-- 33b93476 English: Time
[1739] = "Время",
-- 66f9cfa2 English: Spell Auto-Repeat Active
[1740] = "Автоповтор заклинания активен",
-- 35f743e1 English: Retribution (Wowhead & wowsims)
[1741] = "Воздаяние (Wowhead и wowsims)",
-- 6fc82107 English: Melee Retribution from level 1 to 70, and the default for any Paladin no other
--     premade fits. Opens each target with Judgement of Wisdom (low mana) or the Crusader, keeps
--     your best seal up (Blood or Martyr, Command, then Righteousness), Crusader Strike, judges
--     only Righteousness, Blood or Martyr (or Command on a stunned target), Exorcism on Undead and
--     Demons, Consecration for three or more enemies with mana to spare. Hammer of Wrath is left to
--     you (Wowhead uses it only on fleeing targets). Reminders: Sanctity, Retribution or Devotion
--     Aura, a Blessing on yourself, a heal after the fight, Avenging Wrath. Seal twisting is a
--     separate premade.
[1742] = "Воздаяние в ближнем бою с 1 по 70 уровень; также используется по умолчанию для любого паладина, которому не подходит другая встроенная ротация. Начинает бой с каждой целью с Правосудия мудрости (при нехватке маны) или Правосудия воина Света, поддерживает вашу лучшую печать (Печать крови или мученика, затем повиновения, затем праведности), Удар воина Света, Правосудие только с Печатью праведности, крови или мученика (или повиновения — по оглушённой цели), Экзорцизм против нежити и демонов, Освящение при трёх и более врагах, если маны с запасом. Молот гнева остаётся за вами (Wowhead применяет его только по убегающим целям). Напоминания: Аура святости, воздаяния или благочестия, благословение на себя, исцеление после боя, Гнев карателя. Твист печатей — отдельная встроенная ротация.",
-- 89f00a09 English: Retribution (Icy Veins)
[1743] = "Воздаяние (Icy Veins)",
-- c68e9ea0 English: Icy Veins' Retribution, an alternative to the recommended Wowhead Retribution
--     premade, off by default: enable it and disable that one, or raise its priority. Judgement of
--     the Crusader once per target, Seal of Righteousness (Command only with a slow weapon, Blood
--     or Martyr once learned), Crusader Strike, Hammer of Wrath and Judgement on cooldown,
--     Consecration on two or more enemies, Exorcism on Undead and Demons, and Holy Shock for Holy
--     levelers. Same reminders as the Wowhead variant.
[1744] = "«Воздаяние» по Icy Veins — альтернатива рекомендуемой встроенной ротации «Воздаяние» от Wowhead, отключена по умолчанию: включите её и выключите ту или повысьте её приоритет. Правосудие воина Света один раз на цель, Печать праведности (Печать повиновения — только с медленным оружием, Печать крови или мученика — как только изучена), Удар воина Света, Молот гнева и Правосудие по готовности, Освящение при двух и более врагах, Экзорцизм против нежити и демонов и Шок небес для паладинов, качающихся в ветке «Свет». Те же напоминания, что и в варианте Wowhead.",
-- 85d846bd English: Retribution seal twisting
[1745] = "Воздаяние, твист печатей",
-- 34a6a34f English: Off by default; enable it if you twist seals (level 64+, Seal of Command and
--     Blood or Martyr). Opens with Judgement of the Crusader, then each swing puts up Seal of
--     Command (rank 1) early and switches to Blood or Martyr in the last 0.4 seconds, Crusader
--     Strike between twists, judges only Blood or Martyr, Exorcism and Consecration only as
--     fillers, and rolls Blood without twisting below 12% mana. Needs a reliable swing timer;
--     latency is not accounted for.
[1746] = "По умолчанию выключена; включите её, если вы твистите печати (с 64 уровня, Печать повиновения и Печать крови или мученика). Начинает бой с Правосудия воина Света, затем перед каждым ударом оружием заранее ставит Печать повиновения (ранг 1) и в последние 0,4 секунды переключается на Печать крови или мученика; Удар воина Света между твистами, Правосудие только с Печатью крови или мученика, Экзорцизм и Освящение лишь как заполнители, а при мане ниже 12% держит Печать крови без твиста. Нужен надёжный таймер ударов оружием; задержка не учитывается.",
-- 316a63c1 English: Protection (Wowhead & wowsims)
[1747] = "Защита (Wowhead и wowsims)",
-- c9c2efbf English: Tanking for the Protection tree or any Paladin with Righteous Fury on. Pulls
--     with Holy Shield, Avenger's Shield and Judgement; against a crushing target (world boss or
--     three or more levels above you) Holy Shield comes first; then Consecration, Exorcism on
--     Undead and Demons, Judgement, Holy Shield, Holy Wrath on undead packs, Avenger's Shield
--     except on crushing targets. Seal of Wisdom on packs when mana is short, Righteousness
--     otherwise. Reminders: Righteous Fury, Devotion Aura, Sanctuary (or Kings, or Wisdom),
--     Avenging Wrath, Lay on Hands. Taunts and target swaps stay with you.
[1748] = "Танкование для ветки «Защита» или для любого паладина с включённым Праведным неистовством. Начинает бой со Щита небес, Щита мстителя и Правосудия; против цели с сокрушительными ударами (мировой босс или цель на три и более уровня выше вас) первым идёт Щит небес; затем Освящение, Экзорцизм против нежити и демонов, Правосудие, Щит небес, Гнев небес против групп нежити, Щит мстителя, кроме целей с сокрушительными ударами. Печать мудрости против групп при нехватке маны, иначе Печать праведности. Напоминания: Праведное неистовство, Аура благочестия, Благословение неприкосновенности (или королей, или мудрости), Гнев карателя, Возложение рук. Провокации и смена целей остаются за вами.",
-- 80b938a1 English: Protection (Icy Veins)
[1749] = "Защита (Icy Veins)",
-- 3ae9045e English: Icy Veins' tanking, an alternative to the recommended Wowhead Protection
--     premade, off by default: enable it and disable that one, or raise its priority. Judgement of
--     the Crusader when nobody keeps it up, Righteousness (Wisdom on packs), Consecration as the
--     main threat, Judgement, Holy Shield, then Avenger's Shield and Hammer of Wrath on cooldown.
--     Same reminders as the Wowhead variant without Avenging Wrath.
[1750] = "«Танкование» по Icy Veins — альтернатива рекомендуемой встроенной ротации «Защита» от Wowhead, отключена по умолчанию: включите её и выключите ту или повысьте её приоритет. Правосудие воина Света, если его никто не поддерживает, Печать праведности (мудрости — против групп), Освящение как основной источник угрозы, Правосудие, Щит небес, затем Щит мстителя и Молот гнева по готовности. Те же напоминания, что и в варианте Wowhead, но без Гнева карателя.",
-- 9d88b75a English: Holy (Icy Veins & Wowhead)
[1751] = "Свет (Icy Veins и Wowhead)",
-- 879586c5 English: Healing for a Holy Paladin in a group, on your friendly target: Lay on Hands or
--     Holy Shock for a dying target, Cleanse (Purify before 42), Holy Shock while moving, Holy
--     Light for heavy damage, rank-5 Holy Light to keep Light's Grace up, Flash of Light otherwise.
--     With a hostile target it keeps Judgement of Wisdom up. Reminders: Concentration Aura,
--     Blessing of Wisdom, Divine Illumination and Divine Favor. A soloing Holy Paladin gets a
--     Retribution premade instead.
[1752] = "Лечение для паладина ветки «Свет» в группе, на дружественной цели: Возложение рук или Шок небес для умирающей цели, Очищение (до 42 уровня — Очистить), Шок небес в движении, Свет небес при сильном уроне, Свет небес 5-го ранга для поддержания Благоволения Света, в остальных случаях Вспышка Света. С враждебной целью поддерживает Правосудие мудрости. Напоминания: Аура сосредоточенности, Благословение мудрости, Божественное просветление и Божественное одобрение. Паладин ветки «Свет», играющий в одиночку, получает вместо этого встроенную ротацию «Воздаяние».",
-- 2261d994 English: Holy (Wowhead tank healing)
[1753] = "Свет (лечение танков, Wowhead)",
-- 63b194ff English: Wowhead's raid tank healing, an alternative to the recommended Holy premade,
--     off by default: enable it and disable that one, or raise its priority. Holy Light whenever
--     your target is missing a tenth of their health, Flash of Light only for small deficits, with
--     the same emergencies, cleansing, Judgement and reminders as the blended Holy premade.
[1754] = "Лечение танков в рейде по Wowhead — альтернатива рекомендуемой встроенной ротации «Свет», отключена по умолчанию: включите её и выключите ту или повысьте её приоритет. Свет небес, как только цели не хватает десятой части здоровья, Вспышка Света — только при небольшой нехватке, с теми же экстренными мерами, очищением, Правосудием и напоминаниями, что и в смешанной встроенной ротации «Свет».",
-- 4396ff42 English: Ranged DPS (wowsims)
[1755] = "Урон в дальнем бою (wowsims)",
-- 2b43c4a1 English: Levels 1–70, every spec. Pulls with Hunter's Mark, Aimed Shot and Auto Shot,
--     keeps Auto Shot running and uses melee strikes when a target reaches you. Before Steady Shot
--     it keeps your Serpent Sting up and spends mana on Aimed, Multi and Arcane Shot only while you
--     have plenty. From level 62: Multi-Shot when ready, Steady Shot straight after each Auto Shot,
--     Arcane Shot to fill the gap, Serpent Sting when solo. With three or more enemies fighting
--     you, Multi-Shot whenever it is ready. Reminds you of aspects (Viper when mana runs low, Hawk
--     again at half mana), pet care, Kill Command, major cooldowns on elites and bosses and
--     Silencing Shot. Pet commands, Misdirection, traps, Volley, melee weaving and Feign Death stay
--     with you.
[1756] = "Уровни 1–70, любая ветка талантов. Начинает бой с Метки охотника, Прицельного выстрела и Автоматической стрельбы, не прерывает Автоматическую стрельбу и использует удары ближнего боя, когда цель добирается до вас. До изучения Верного выстрела поддерживает Укус змеи и тратит ману на Прицельный, Чародейский выстрел и Залп только при большом запасе маны. С 62 уровня: Залп по готовности, Верный выстрел сразу после каждого автоматического выстрела, Чародейский выстрел, чтобы заполнить паузу, Укус змеи в одиночной игре. Если с вами сражаются три и более врага — Залп всякий раз, когда он готов. Напоминает о аспектах (Дух гадюки при нехватке маны, снова Дух ястреба на половине маны), уходе за питомцем, Команде «Взять!», крупных способностях с восстановлением против элитных противников и боссов и о Глушащем выстреле. Команды питомцу, Перенаправление, ловушки, Град стрел, вплетение ударов ближнего боя и Притвориться мертвым остаются за вами.",
-- 825c84d1 English: Ranged DPS (Wowhead)
[1757] = "Урон в дальнем бою (Wowhead)",
-- fb9ad1ee English: Levels 1–70, every spec, following Wowhead's raid advice. Same pull, melee,
--     leveling shots, multi-target Multi-Shot and reminders as the wowsims version, but once Steady
--     Shot is learned it only offers Multi-Shot and Steady Shot after each Auto Shot: no Arcane
--     Shot filler (except while moving), no Serpent Sting and no Aspect of the Viper reminder. Pet
--     commands, Misdirection, traps, Volley, melee weaving and Feign Death stay with you. An
--     alternative to the recommended wowsims ranged premade, off by default: enable it and disable
--     that one, or raise its priority.
[1758] = "Уровни 1–70, любая ветка талантов, по рейдовым советам Wowhead. Те же начало боя, ближний бой, выстрелы для прокачки, Залп против нескольких целей и напоминания, что и в версии wowsims, но после изучения Верного выстрела после каждого автоматического выстрела предлагает только Залп и Верный выстрел: без Чародейского выстрела как заполнителя (кроме как в движении), без Укуса змеи и без напоминания о Духе гадюки. Команды питомцу, Перенаправление, ловушки, Град стрел, вплетение ударов ближнего боя и Притвориться мертвым остаются за вами. Альтернатива рекомендуемой встроенной ротации «Дальний бой» (wowsims), отключена по умолчанию: включите её и выключите ту или повысьте её приоритет.",
-- 469b61e4 English: Melee DPS (wowsims)
[1759] = "Урон в ближнем бою (wowsims)",
-- a600e4ad English: Levels 1–70, every spec. From stealth: Premeditation, then Cheap Shot solo or
--     Garrote in a group, otherwise Ambush (with a dagger in the main hand). In combat: Riposte,
--     Slice and Dice from two combo points (renewed in its last two seconds), Eviscerate on a
--     target about to die, and at five points Rupture when it will last (not while Blade Flurry
--     cleaves), otherwise Eviscerate. Builds with Mutilate or Backstab (dagger) when the target is
--     not attacking you, otherwise Hemorrhage or Sinister Strike. Reminds you of missing poisons,
--     Kick, Blade Flurry and Adrenaline Rush, Cold Blood and Evasion. Expose Armor, Kidney Shot,
--     Feint, Vanish and positioning stay with you.
[1760] = "Уровни 1–70, любая ветка талантов. Из незаметности: Умысел, затем Подлый трюк в одиночку или Гаррота в группе, иначе Внезапный удар (с кинжалом в основной руке). В бою: Ответный удар, Мясорубка от двух очков серии (обновляется в последние две секунды), Потрошение по цели, которая вот-вот умрёт, а на пяти очках — Рваная рана, если она успеет отработать (но не во время Шквала клинков), иначе Потрошение. Набирает очки Расправой или Ударом в спину (кинжал), когда цель не атакует вас, иначе Кровоизлиянием или Коварным ударом. Напоминает об отсутствующих ядах, Пинке, Шквале клинков и Выбросе адреналина, Хладнокровии и Ускользании. Ослабление доспеха, Удар по почкам, Ложный выпад, Исчезновение и позиционирование остаются за вами.",
-- 5f9b3940 English: Melee DPS (Wowhead)
[1761] = "Урон в ближнем бою (Wowhead)",
-- 19e52877 English: Levels 1–70, every spec, following Wowhead. Same stealth openers, builders and
--     reminders as the wowsims version, but Slice and Dice starts from one combo point and every
--     five-point finisher is Eviscerate: no Rupture. Expose Armor, Kidney Shot, Feint, Vanish and
--     positioning stay with you. An alternative to the recommended wowsims melee DPS premade, off
--     by default: enable it and disable that one, or raise its priority.
[1762] = "Уровни 1–70, любая ветка талантов, по Wowhead. Те же атаки из незаметности, приёмы набора очков и напоминания, что и в версии wowsims, но Мясорубка ставится уже с одного очка серии, а каждый добивающий приём на пяти очках — Потрошение: без Рваной раны. Ослабление доспеха, Удар по почкам, Ложный выпад, Исчезновение и позиционирование остаются за вами. Альтернатива рекомендуемой встроенной ротации «Урон в ближнем бою» (wowsims), отключена по умолчанию: включите её и выключите ту или повысьте её приоритет.",
-- d05e07b7 English: Balance
[1763] = "Баланс",
-- 8177cc43 English: Caster Balance from level 1 to 70, and the default for any Druid no other
--     premade fits. Pulls with Starfire (Wrath before 20), Insect Swarm and Moonfire while moving,
--     Faerie Fire in a group, Hurricane for three or more enemies, Moonfire when it has run out and
--     you have 30% mana, Starfire on Nature's Grace, Wrath against a target in melee, then Starfire
--     (Wrath before it is learned). No advice in Cat, Bear or travel forms. Reminders: Mark of the
--     Wild, Thorns while solo, Omen of Clarity, Moonkin Form, Force of Nature on a long fight,
--     Innervate when low.
[1764] = "Заклинатель ветки «Баланс» с 1 по 70 уровень; также используется по умолчанию для любого друида, которому не подходит другая встроенная ротация. Начинает бой Звездным огнем (до 20 уровня — Гневом), Рой насекомых и Лунный огонь в движении, Волшебный огонь в группе, Гроза при трёх и более врагах, Лунный огонь, когда он истёк и у вас есть 30% маны, Звездный огонь при Благоволении природы, Гнев по цели в ближнем бою, затем Звездный огонь (Гнев, пока он не изучен). В облике кошки, медведя и походном облике советов нет. Напоминания: Знак дикой природы, Шипы в одиночной игре, Знамение ясности, Облик лунного совуха, Сила Природы в долгом бою, Озарение при нехватке маны.",
-- 9a2fa639 English: Feral (Icy Veins, Warcraft Tavern & wowsims)
[1765] = "Сила зверя (Icy Veins, Warcraft Tavern и wowsims)",
-- 43a0ca32 English: Cat and bear for the Feral tree, following your form. Cat: stealth opener
--     (Pounce, Ravage or Shred), Faerie Fire (Feral), Rip at four combo points on a target that
--     lives, Ferocious Bite between Rips without Clearcasting, Mangle kept up, Shred from behind or
--     Mangle/Claw when the target is on you. Bear: Faerie Fire, Lacerate saved before it drops,
--     Demoralizing Roar unless a warrior's Shout is up, Swipe for packs, Mangle, five Lacerates,
--     Swipe. In caster form it suggests Cat (or Bear) Form. Reminders: Mark, Thorns, Omen, Maul
--     with spare rage, Tiger's Fury before a pull, Frenzied Regeneration. Powershifting is an
--     optional step that starts off (it needs a powershift macro).
[1766] = "Кошка и медведь для ветки «Сила зверя» в зависимости от вашего облика. Кошка: атака из незаметности (Наскок, Накинуться или Полоснуть), Волшебный огонь (сила зверя), «Разорвать» на четырёх очках серии по цели, которая проживёт достаточно долго, Свирепый укус между «Разорвать» без Ясности мысли, поддержание Увечья, Полоснуть из-за спины или Увечье/Когти, когда цель бьёт вас. Медведь: Волшебный огонь, Растерзать обновляется до того, как спадёт, Устрашающий рев, если не висит крик воина, Размах против групп, Увечье, пять наложений Растерзать, Размах. В облике заклинателя предлагает Облик кошки (или медведя). Напоминания: Знак, Шипы, Знамение, Трепка при лишней ярости, Тигриное неистовство перед боем, Неистовое восстановление. Смена облика ради энергии (powershifting) — необязательный шаг, по умолчанию выключенный (нужен макрос для powershift).",
-- 4c55a525 English: Feral (Wowhead)
[1767] = "Сила зверя (Wowhead)",
-- 9092413a English: Wowhead's Feral, an alternative to the recommended Icy Veins Feral premade, off
--     by default: enable it and disable that one, or raise its priority. Rip whenever it is down at
--     four combo points and Ferocious Bite only on a target about to die (no bite-weaving); bears
--     spend free global cooldowns on Lacerate before Swipe. Innervate when a cat runs low on mana.
--     Otherwise the same as the Icy Veins variant.
[1768] = "«Сила зверя» по Wowhead — альтернатива рекомендуемой встроенной ротации «Сила зверя» от Icy Veins, отключена по умолчанию: включите её и выключите ту или повысьте её приоритет. Разорвать всякий раз, когда он спал, на четырёх очках серии, а Свирепый укус — только по цели, которая вот-вот умрёт (без вплетения укусов); медведь тратит свободные ГКД на Растерзать перед Размахом. Озарение, когда у кошки кончается мана. В остальном — как вариант Icy Veins.",
-- 6a3c6c77 English: Restoration
[1769] = "Исцеление",
-- da5557c1 English: Healing for the Restoration tree on your friendly target (or yourself): Healing
--     Touch after Nature's Swiftness, Swiftmend a dying target that has your Rejuvenation or
--     Regrowth, three rolling Lifeblooms in combat, Rejuvenation and Regrowth when missing, then
--     Regrowth in Tree of Life or Healing Touch outside it. A hostile target gets Moonfire and
--     Wrath for soloing. Reminders: Mark, Omen, Tree of Life, Nature's Swiftness, Tranquility,
--     Innervate and Rebirth. Choosing whom to heal and downranking stay with you.
[1770] = "Лечение для ветки «Исцеление» на дружественной цели (или на себе): Целительное прикосновение после Природной стремительности, Быстрое восстановление на умирающую цель с вашим Омоложением или Восстановлением, три постоянно обновляемых наложения Жизнецвета в бою, Омоложение и Восстановление, если их нет, затем Восстановление в облике Древа жизни или Целительное прикосновение вне его. Против враждебной цели — Лунный огонь и Гнев для одиночной игры. Напоминания: Знак, Знамение, Древо жизни, Природная стремительность, Спокойствие, Озарение и Возрождение. Кого лечить и понижение ранга заклинаний остаются за вами.",
-- 469b61e4 English: Melee DPS (wowsims)
[1771] = "Урон в ближнем бою (wowsims)",
-- e30bf8c3 English: Levels 1–70, Arms or Fury. Charges to pull, then Victory Rush, Intercept,
--     Rampage, and Whirlwind when two or more enemies fight you (Thunder Clap before it is
--     learned). With Bloodthirst or Mortal Strike: that strike, Whirlwind with rage to spare,
--     Execute, Overpower. Before them: Whirlwind, Execute, Overpower, Rend. Spare rage goes to
--     Devastate or Sunder Armor, then Hamstring. Reminds you of Battle Shout, Bloodrage, Heroic
--     Strike or Cleave as rage dumps, Sweeping Strikes, Death Wish, Recklessness and interrupts.
--     Slam timing, stance dancing and Berserker Rage stay with you.
[1772] = "Уровни 1–70, «Оружие» или «Неистовство». Начинает бой Рывком, затем Победный раж, Перехват, Буйство и Вихрь, когда с вами сражаются два и более врага (до его изучения — Удар грома). С Кровожадностью или Смертельным ударом: этот удар, Вихрь при лишней ярости, Казнь, Превосходство. До их изучения: Вихрь, Казнь, Превосходство, Кровопускание. Лишняя ярость уходит на Разрушение или Раскол брони, затем на Подрезать сухожилия. Напоминает о Боевом крике, Кровавой ярости, Ударе героя или Рассекающем ударе для сброса ярости, Размашистых ударах, Инстинкте смерти, Безрассудстве и прерываниях. Тайминг Сокрушения, смена стоек и Ярость берсерка остаются за вами.",
-- 6d10d944 English: Melee DPS (Icy Veins)
[1773] = "Урон в ближнем бою (Icy Veins)",
-- c50ff4f3 English: Levels 1–70, Arms or Fury, following Icy Veins. Same pull, reminders and
--     leveling steps as the wowsims version, but with Mortal Strike Execute comes first, with
--     Bloodthirst Execute comes right after it, Whirlwind follows without holding rage, and
--     Hamstring only near full rage. Slam timing, stance dancing and Berserker Rage stay with you.
--     An alternative to the recommended wowsims melee DPS premade, off by default: enable it and
--     disable that one, or raise its priority.
[1774] = "Уровни 1–70, «Оружие» или «Неистовство», по Icy Veins. Те же начало боя, напоминания и шаги для прокачки, что и в версии wowsims, но со Смертельным ударом первой идёт Казнь, с Кровожадностью Казнь идёт сразу после неё, Вихрь следует без накопления ярости, а Подрезать сухожилия — только при почти полной ярости. Тайминг Сокрушения, смена стоек и Ярость берсерка остаются за вами. Альтернатива рекомендуемой встроенной ротации «Урон в ближнем бою» (wowsims), отключена по умолчанию: включите её и выключите ту или повысьте её приоритет.",
-- 871d5911 English: Tank (Wowhead)
[1775] = "Танк (Wowhead)",
-- 91dfa1ce English: Levels 10–70, chosen while you are in Defensive Stance. Shield Slam, Revenge,
--     Thunder Clap and Demoralizing Shout kept up on elites and bosses, then Devastate or Sunder
--     Armor. On packs: Thunder Clap and Demoralizing Shout first. Reminds you of Shield Block (with
--     a shield equipped) against bosses and higher-level enemies, Heroic Strike or Cleave, Battle
--     Shout, Bloodrage, Shield Bash and emergency Last Stand and Shield Wall. Taunting and other
--     utility stay with you.
[1776] = "Уровни 10–70; выбирается, пока вы в Оборонительной стойке. Сокрушение щитом, Реванш, Удар грома и Деморализующий крик поддерживаются на элитных противниках и боссах, затем Разрушение или Раскол брони. Против групп: сначала Удар грома и Деморализующий крик. Напоминает о Блоке щитом (при надетом щите) против боссов и врагов более высокого уровня, Ударе героя или Рассекающем ударе, Боевом крике, Кровавой ярости, Ударе щитом, а в экстренных случаях — о «Ни шагу назад» и Глухой обороне. Провокация и прочие вспомогательные способности остаются за вами.",
-- ea76d926 English: Tank (Icy Veins)
[1777] = "Танк (Icy Veins)",
-- aa141592 English: Levels 10–70, chosen while you are in Defensive Stance, following Icy Veins.
--     Shield Slam, Revenge, then Devastate or Sunder Armor, with Rend at the start of a fight until
--     Shield Slam is learned. On packs: Thunder Clap, and Demoralizing Shout against elites. Shield
--     Block is reminded whenever your target is attacking you and you carry a shield. Taunting and
--     other utility stay with you. An alternative to the recommended Wowhead tank premade, off by
--     default: enable it and disable that one, or raise its priority.
[1778] = "Уровни 10–70; выбирается, пока вы в Оборонительной стойке, по Icy Veins. Сокрушение щитом, Реванш, затем Разрушение или Раскол брони, а в начале боя — Кровопускание, пока не изучено Сокрушение щитом. Против групп: Удар грома, а против элитных противников — Деморализующий крик. О Блоке щитом напоминает всякий раз, когда цель атакует вас и у вас есть щит. Провокация и прочие вспомогательные способности остаются за вами. Альтернатива рекомендуемой встроенной ротации танка от Wowhead, отключена по умолчанию: включите её и выключите ту или повысьте её приоритет.",
-- 3adec7ba English: Damage (Icy Veins)
[1779] = "Урон (Icy Veins)",
-- 9b0711bb English: Damage from level 1 to 70, used whenever the healer premade does not apply.
--     Smite and wand early, then Mind Blast, Shadow Word: Pain, Mind Flay, Shadowform, Vampiric
--     Touch and Shadow Word: Death as you learn them; DoTs before Mind Blast; a dying target is
--     wanded when solo. Holy and Discipline questers get Holy Fire and Smite. Reminders: Inner
--     Fire, Fortitude, racial buffs, Inner Focus, Shadowfiend. A Mind Flay past its first tick is
--     cut short for a ready Mind Blast, or Shadow Word: Death above half health. Shields and
--     healing stay with you.
[1780] = "Урон с 1 по 70 уровень; используется всегда, когда не подходит встроенная ротация лекаря. Сначала Кара и жезл, затем Взрыв разума, Слово Тьмы: Боль, Пытка разума, Облик Тьмы, Прикосновение вампира и Слово Тьмы: Смерть по мере изучения; DoT — раньше Взрыва разума; в одиночной игре умирающую цель добивает жезл. Жрецы веток «Свет» и «Послушание», выполняющие задания, получают Священный огонь и Кару. Напоминания: Внутренний огонь, Стойкость, расовые положительные эффекты, Внутреннее сосредоточение, Исчадие Тьмы. Пытка разума, прошедшая первый такт, обрывается ради готового Взрыва разума или Слова Тьмы: Смерть при здоровье цели выше половины. Щиты и лечение остаются за вами.",
-- ce79d246 English: Damage (Wowhead)
[1781] = "Урон (Wowhead)",
-- fe006eaa English: Damage after Wowhead's guides, an alternative to the recommended Icy Veins
--     damage premade, off by default: enable it and disable that one, or raise its priority. Mind
--     Blast opens and goes before DoT refreshes, Vampiric Embrace only when your health drops, and
--     a dying target gets spells instead of the wand. Otherwise the same as the recommended
--     premade.
[1782] = "Урон по руководствам Wowhead — альтернатива рекомендуемой встроенной ротации урона от Icy Veins, отключена по умолчанию: включите её и выключите ту или повысьте её приоритет. Взрыв разума начинает бой и идёт раньше обновления DoT, Объятия вампира — только когда падает ваше здоровье, а умирающую цель добивают заклинаниями, а не жезлом. В остальном — как рекомендуемая встроенная ротация.",
-- d0f0e9e6 English: Healer (Wowhead)
[1783] = "Лекарь (Wowhead)",
-- d31781e0 English: Healing in a group when Holy or Discipline is your main talent tree. It advises
--     on the friendly unit you target; you choose whom to heal. Prayer of Mending before pulls and
--     whenever ready, Renew, Power Word: Shield in emergencies, dispels, Circle of Healing or
--     Prayer of Healing for group damage, Binding, Flash and Greater Heal, and Greater Heal rank 1
--     as a cheap top-up. With an enemy targeted it offers light damage.
[1784] = "Лечение в группе, когда «Свет» или «Послушание» — ваша основная ветка талантов. Советы даются для дружественного юнита в цели; кого лечить, выбираете вы. Молитва восстановления перед боем и всякий раз по готовности, Обновление, Слово силы: Щит в экстренных случаях, рассеивание, Круг исцеления или Молитва исцеления при уроне по группе, Связующее, Быстрое и Сильное исцеление, а также Сильное исцеление 1-го ранга как дешёвая подпитка. Если в цели враг, предлагает немного урона.",
-- 45321807 English: Healer (Icy Veins)
[1785] = "Лекарь (Icy Veins)",
-- e31d4277 English: Healing after Icy Veins' order: Shield, dispels, Binding Heal, Renew, Flash
--     Heal, Greater Heal (any rank), group heals, and Prayer of Mending last. You choose whom to
--     heal. An alternative to the recommended Wowhead healer premade, off by default: enable it and
--     disable that one, or raise its priority.
[1786] = "Лечение в порядке Icy Veins: щит, рассеивание, Связующее исцеление, Обновление, Быстрое исцеление, Сильное исцеление (любого ранга), групповое лечение и последней — Молитва восстановления. Кого лечить, выбираете вы. Альтернатива рекомендуемой встроенной ротации лекаря от Wowhead, отключена по умолчанию: включите её и выключите ту или повысьте её приоритет.",
-- 8283f17a English: All trees (Icy Veins)
[1787] = "Все ветки (Icy Veins)",
-- da4da042 English: Every talent tree from level 1 to 70. Curse, then Unstable Affliction,
--     Immolate, Corruption and Siphon Life as learned, Shadow Bolt or Incinerate; Nightfall and
--     Backlash procs first; Seed, Hellfire and Shadowfury for three or more enemies. Solo it drains
--     when hurt, Life Taps, wands, and uses Drain Soul or a finisher on a dying target. Reminders:
--     Fel Armor, Demon Armor or Demon Skin, your demon, sacrifice, Soul Link, Amplify Curse and
--     Soulshatter. Fears and other curses stay with you.
[1788] = "Все ветки талантов с 1 по 70 уровень. Проклятие, затем Нестабильное колдовство, Жертвенный огонь, Порча и Вытягивание жизни по мере изучения, Стрела Тьмы или Испепеление; сначала срабатывания Сумерек и Отдачи; Семя порчи, Адское пламя и Неистовство Тьмы при трёх и более врагах. В одиночной игре похищает жизнь, когда вы ранены, использует Жизнеотвод, жезл, а на умирающей цели — Похищение души или добивающее заклинание. Напоминания: Доспех Скверны, Демонический доспех или Шкура демона, ваш демон, жертвоприношение, Связка души, Усиление проклятия и Раскол души. Страх и прочие проклятия остаются за вами.",
-- e3790b25 English: Drain-tank (Wowhead)
[1789] = "Дрейн-танк (Wowhead)",
-- 522ed69f English: Warlock after Wowhead's guides, an alternative to the recommended Icy Veins
--     Warlock premade, off by default: enable it and disable that one, or raise its priority. Solo
--     it drain-tanks: Drain Life is the filler once your DoTs are up and Immolate and Siphon Life
--     are kept for elite mobs. In a group Immolate always goes on, after Corruption and Siphon
--     Life. Otherwise the same as the recommended premade.
[1790] = "Чернокнижник по руководствам Wowhead — альтернатива рекомендуемой встроенной ротации «Чернокнижник» от Icy Veins, отключена по умолчанию: включите её и выключите ту или повысьте её приоритет. В одиночной игре танкует похищением (дрейн-танк): Похищение жизни становится основным заклинанием, как только ваши DoT наложены, а Жертвенный огонь и Вытягивание жизни приберегаются для элитных противников. В группе Жертвенный огонь накладывается всегда, после Порчи и Вытягивания жизни. В остальном — как рекомендуемая встроенная ротация.",
-- a97bc1c7 English: Apply changes to this selected item list. Other settings keep their own Apply
--     action.
[1791] = "Применить изменения к этому выбранному списку предметов. У других настроек своя кнопка «Применить».",
-- 4cec1d75 English: Choose an item list before editing.
[1792] = "Перед правкой выберите список предметов.",
-- 550c388b English: The item list changed elsewhere. Close and reopen it before applying.
[1793] = "Список предметов изменён в другом месте. Закройте и откройте его заново перед применением.",
-- 67559dc7 English: Native settings page unavailable: %s
[1794] = "Встроенная страница настроек недоступна: %s",
-- 0f6314b0 English: The native rotation editor is unavailable.
[1795] = "Встроенный редактор ротаций недоступен.",
-- 4850b174 English: Required
[1796] = "Обязательное",
-- 9bcec068 English: Required field references need review. Apply keeps the displayed root
--     requirements.
[1797] = "Ссылки на обязательные поля требуют проверки. «Применить» сохраняет показанные требования корневого уровня.",
-- c463dfb4 English: Required root fields must have a value before this condition can run. Rename,
--     reorder and duplicate keep this flag; removing the field removes its requirement. Moving it
--     into a nested structure makes it optional. Undo restores both. Callback code is unchanged.
[1798] = "Обязательные поля корневого уровня должны иметь значение, прежде чем условие сможет выполняться. Переименование, перемещение и дублирование сохраняют этот флаг; удаление поля снимает требование. Перемещение во вложенную структуру делает поле необязательным. «Отменить» восстанавливает оба состояния. Код обратного вызова не меняется.",
-- 8b8cd45b English: Copy condition description
[1799] = "Копировать описание условия",
-- b5739be0 English: This condition exceeds the supported editor limits.
[1800] = "Это условие превышает поддерживаемые редактором пределы.",
-- df58aeb6 English: Proc Glow
[1801] = "Свечение срабатывания",
-- dce1c179 English: Loop duration
[1802] = "Длительность цикла",
-- a4f0db33 English: Start burst
[1803] = "Начальная вспышка",
-- b89fd7fd English: Proc Glow is unavailable on this client; Pixel glow will be used.
[1804] = "«Свечение срабатывания» недоступно на этом клиенте; будет использовано свечение «Пиксели».",
-- 34ae0a26 English: Rotation data requires recovery: %s
[1805] = "Данные ротации требуют восстановления: %s",
-- 8b4e37b9 English: Copies belong to your Class unless This character is selected. Replacement
--     keeps its original owner.
[1806] = "Копии принадлежат вашему классу, если не выбран «Этот персонаж». Замена сохраняет исходного владельца.",
-- 0faa3bd8 English: Archive report truncated; saved data is unchanged.
[1807] = "Отчёт архива обрезан; сохранённые данные не изменены.",
-- 414c7fd3 English: Recover unassigned rotations
[1808] = "Восстановить ротации без владельца",
-- 291f821c English: Ownership required
[1809] = "Требуется владелец",
-- cd16196a English: These records have no assigned owner. Choose Class or This character
--     explicitly. No ownership is inferred from names, spells or profile history.
[1810] = "У этих записей нет назначенного владельца. Явно выберите «Класс» или «Этот персонаж». Владелец не определяется по названиям, заклинаниям или истории профиля.",
-- ce112847 English: Recovery unavailable: %s
[1811] = "Восстановление недоступно: %s",
-- af7356f1 English: Unassigned rotation archive
[1812] = "Архив ротаций без владельца",
