[1836] = "Семейство клиента: %s (%s)",
-- ff3a37e2 English: declared; unverified
[1837] = "заявлено; не проверено",
-- 60945d49 English: unsupported
[1838] = "не поддерживается",
-- b0fa65e4 English: Native acceptance: unverified. Coverage: recent update receipts only; no quest
--     progress, completion or rotation selection.
[1839] = "Встроенная приёмка: не проверена. Охват: только недавние уведомления об обновлениях; без прогресса заданий, их выполнения и выбора ротации.",
-- 0dfbd5e8 English: Questie is optional and disabled by default. Apply saves this profile
--     preference. No background polling is used.
