--     tuple positions.
[2803] = "Вид наблюдения: cast или channel. У них разные позиции признака прерываемости во встроенном кортеже.",
-- 02905e55 English: Observation, history, work-limit or arithmetic availability reason.
[2804] = "Причина недоступности наблюдения, истории, предела работы или арифметики.",
-- 966b23c3 English: Observe a fresh protected zero-argument GetTime for a needed health forecast.
--     Require readability and a finite number; preserve signed and fractional values without adding
--     a monotonic, integral or nonnegative restriction. No clock cache or extra native query is
--     used.
[2805] = "Получить свежее значение защищённого вызова GetTime без аргументов для нужного прогноза здоровья. Требуются читаемость и конечное число; знаковые и дробные значения сохраняются без ограничений монотонности, целочисленности или неотрицательности. Кэш часов и дополнительные встроенные запросы не используются.",
-- 9d79dc0d English: Observe a point resource that the client reports in fragments (Mists of
--     Pandaria Burning Embers). Current uses exactly UnitPower(unit,powerType,true) and maximum
--     UnitPowerMax(unit,powerType,true); the result is divided by Blizzard MAX_POWER_PER_EMBER
--     (10), so 35 fragments are 3.5. Probe policy only. Missing, failed, restricted or malformed
--     data remains unavailable; it never falls back to the whole-unit query. No cache is added.
[2806] = "Наблюдать очки ресурса, которые клиент сообщает частями (Раскаленные угли в Mists of Pandaria). Для current используется ровно UnitPower(unit,powerType,true), для maximum — UnitPowerMax(unit,powerType,true); результат делится на MAX_POWER_PER_EMBER от Blizzard (10), поэтому 35 частей — это 3,5. Только политика проверки. Отсутствующие, неудачные, ограниченные или повреждённые данные остаются недоступными; запрос в целых единицах никогда не используется как запасной вариант. Кэш не добавляется.",
-- eb0c20b2 English: Observe a readable raw unit level on known clients. A readable absent unit
--     returns exists=false; present units require a positive finite integer UnitLevel. Unknown boss
--     levels, missing, failed, restricted or malformed observations return nil with a reason. This
--     does not use effective or scaled levels.
[2807] = "Наблюдать читаемый исходный уровень юнита на известных клиентах. Читаемо отсутствующий юнит возвращает exists=false; для присутствующих юнитов нужен положительный конечный целый UnitLevel. Неизвестный уровень босса, отсутствующие, неудачные, ограниченные или повреждённые наблюдения возвращают nil с причиной. Эффективные или масштабированные уровни не используются.",
-- bc5313d0 English: Observe a selected unit role on probe- and restricted-policy clients without
--     issuing inspection requests. Known unit absence returns false. Prefer the callable modern
--     inspection API, with legacy fallback only when that callable is absent; a selected failure
--     never falls through. Require a positive finite integral specialization ID and consume only
--     role return five from the exact one-argument GetSpecializationInfoByID call. Missing, failed,
--     restricted or malformed required facts are unavailable; readable nonempty future role strings
--     remain exact.
[2808] = "Наблюдать роль выбранного юнита на клиентах с политикой проверки или ограничения без запросов осмотра. Известное отсутствие юнита возвращает false. Предпочитается вызываемый современный API осмотра, а старый вариант — только если вызываемого нет; ошибка выбранного варианта никогда не переходит к другому. Требуется положительный конечный целый ID специализации, и используется только пятое возвращаемое значение (роль) точного вызова GetSpecializationInfoByID с одним аргументом. Отсутствующие, неудачные, ограниченные или повреждённые обязательные факты недоступны; читаемые непустые будущие строки ролей сохраняются точно.",
-- 3668cf1e English: Observe a unit casting or channeling on probe- and restricted-policy clients. A
--     known absent unit or a readable inactive result returns active=false. Active records contain
--     name, or nameReason when the name is secret (the unit is still casting), and independently
--     available remainingSeconds, durationSeconds, interruptible and spellID fields, with
--     remainingReason, durationReason, interruptibleReason or spellReason when an optional field is
--     unavailable. Missing, failed or restricted presence observations return nil with a reason.
[2809] = "Наблюдать произнесение или поддержание заклинания юнитом на клиентах с политикой проверки или ограничения. Известное отсутствие юнита или читаемый неактивный результат возвращает active=false. Активные записи содержат name либо nameReason, если имя секретно (юнит всё равно произносит заклинание), а также независимо доступные поля remainingSeconds, durationSeconds, interruptible и spellID с remainingReason, durationReason, interruptibleReason или spellReason, если необязательное поле недоступно. Отсутствующие, неудачные или ограниченные наблюдения присутствия возвращают nil с причиной.",
-- 740dd187 English: Observe creature identity from native UnitCreatureType return two on probe- and
--     restricted-policy clients. Check exact UnitExists(unit) first; readable false returns false
--     without requiring or calling creature metadata. A present unit requires a readable finite
--     numeric ID; the unused localized name does not affect availability. Preserve signed,
--     fractional, zero and future finite IDs as known values. Missing, failed, nil, restricted or
--     malformed required facts return nil with a reason. No creature enumeration, translated
--     caption comparison or longterm cache is added.
[2810] = "Наблюдать идентичность существа по второму возвращаемому значению встроенного UnitCreatureType на клиентах с политикой проверки или ограничения. Сначала проверяется точный UnitExists(unit); читаемое false возвращает false без запроса метаданных существа. Для присутствующего юнита нужен читаемый конечный числовой ID; неиспользуемое локализованное название на доступность не влияет. Знаковые, дробные, нулевые и будущие конечные ID сохраняются как известные значения. Отсутствующие, неудачные, nil, ограниченные или повреждённые обязательные факты возвращают nil с причиной. Перечисление существ, сравнение переведённых подписей и долговременный кэш не добавляются.",
-- 075b71e7 English: Observe death or ghost state, or friendliness to the player, for the exact
--     selected unit on probe- and restricted-policy clients. A missing, failed, restricted or
--     malformed required observation is unavailable. Unit absence is unavailable rather than a
--     negative match, including under NOT. No cross-poll state is retained.
[2811] = "Наблюдать состояние смерти или призрака либо дружелюбие к игроку для точного выбранного юнита на клиентах с политикой проверки или ограничения. Отсутствующее, неудачное, ограниченное или повреждённое обязательное наблюдение недоступно. Отсутствие юнита — это «недоступно», а не отрицательное совпадение, в том числе под НЕ. Состояние между опросами не сохраняется.",
-- 87176204 English: Observe exact pet existence and optionally its formatted GetUnitName display
--     name. Presence-only queries never require name data. Known absence skips the name query.
--     Present pets require a readable nonempty name only when requested; required missing, failed,
--     nil, restricted or malformed observations return nil with a reason. The display helper is
--     called with its single original pet argument, without UnitName fallback or inferred bar,
--     health or ability state.
[2812] = "Наблюдать точное существование питомца и, при необходимости, его отформатированное отображаемое имя через GetUnitName. Запросы только присутствия никогда не требуют имени. При известном отсутствии запрос имени пропускается. Для присутствующих питомцев читаемое непустое имя требуется только по запросу; отсутствующие, неудачные, nil, ограниченные или повреждённые обязательные наблюдения возвращают nil с причиной. Помощник отображения вызывается с единственным исходным аргументом питомца, без запасного UnitName и без выводов о панели, здоровье или способностях.",
-- 2280ad22 English: Observe exact selected-unit existence and optionally its class filename for
--     point-resource conditions. Known absence returns exists=false without reading class. Present
--     units require only UnitClass return two when requested; unused localized names and IDs do not
--     affect availability. Required missing, failed, restricted or malformed observations remain
--     unavailable. This does not select a resource or cache identity.
[2813] = "Наблюдать точное существование выбранного юнита и, при необходимости, имя файла его класса для условий по очкам ресурса. Известное отсутствие возвращает exists=false без чтения класса. Для присутствующих юнитов по запросу нужно только второе возвращаемое значение UnitClass; неиспользуемые локализованные названия и ID на доступность не влияют. Отсутствующие, неудачные, ограниченные или повреждённые обязательные наблюдения остаются недоступными. Ресурс не выбирается, идентичность не кэшируется.",
-- 9b79981c English: Observe explicit mana or the current raw power resource on supported readable
--     clients. Select resource identities from the live PowerType enum; explicit mana never falls
--     back to the current bar. Known absence returns exists=false; missing, failed, restricted or
--     malformed observations return nil with a reason. Current-mode quantities preserve signed
--     native resources; explicit mana is nonnegative. Request maximum only when needed; percentage
--     consumers must require a positive maximum.
[2814] = "Наблюдать явно ману или текущий исходный ресурс на поддерживаемых читаемых клиентах. Идентичность ресурса выбирается из действующего перечисления PowerType; явная мана никогда не заменяется текущей полосой. Известное отсутствие возвращает exists=false; отсутствующие, неудачные, ограниченные или повреждённые наблюдения возвращают nil с причиной. Количества в режиме current сохраняют знак встроенных ресурсов; явная мана неотрицательна. Максимум запрашивается только при необходимости; потребители процентов должны требовать положительный максимум.",
-- 278a17a4 English: Observe glyph sockets on verified Wrath, Cata and Mists client layouts. Returns
--     slots and a complete flag. Each slot has active=false when known locked or empty, active=true
--     plus spellID when occupied, or nil active plus reason when unavailable. Unknown layouts and
--     failed count queries return nil with a reason. This does not compare item names or prove
--     exact item-to-spell identity.
[2815] = "Наблюдать гнёзда символов на проверенных раскладках клиентов Wrath, Cata и Mists. Возвращает slots и флаг complete. У каждой ячейки active=false, если она известно заблокирована или пуста, active=true и spellID, если занята, или active=nil и причина, если недоступна. Неизвестные раскладки и неудачные запросы количества возвращают nil с причиной. Названия предметов не сравниваются, точное соответствие предмета заклинанию не доказывается.",
-- 24ad932a English: Observe one consumed native unit metadata field after checking UnitExists:
--     class uses UnitClass return two, creature uses the localized UnitCreatureType name, and
--     classification uses UnitClassification. A readable absent unit returns false without querying
--     metadata. Unused tuple fields do not affect availability; a required missing, failed, nil,
--     restricted or malformed value returns nil with a reason. No player class, GUID, enum or
--     translation inference is added.
[2816] = "Наблюдать одно используемое поле встроенных метаданных юнита после проверки UnitExists: class — второе значение UnitClass, creature — локализованное название UnitCreatureType, classification — UnitClassification. Читаемо отсутствующий юнит возвращает false без запроса метаданных. Неиспользуемые поля кортежа на доступность не влияют; отсутствующее, неудачное, nil, ограниченное или повреждённое обязательное значение возвращает nil с причиной. Класс игрока, GUID, перечисления или переводы не выводятся.",
-- 641cce1a English: Observe one current unit flag: combat uses UnitAffectingCombat, enemy uses
--     UnitIsEnemy with player as the first unit, and pvp uses UnitIsPVP. A readable absent unit
--     returns false without querying the flag. Required missing, failed, restricted or malformed
--     observations return nil with a reason. This preserves the exact selected unit and does not
--     infer friendliness, attackability or other unit states.
[2817] = "Наблюдать один текущий флаг юнита: combat — UnitAffectingCombat, enemy — UnitIsEnemy с player первым юнитом, pvp — UnitIsPVP. Читаемо отсутствующий юнит возвращает false без запроса флага. Отсутствующие, неудачные, ограниченные или повреждённые обязательные наблюдения возвращают nil с причиной. Точный выбранный юнит сохраняется; дружелюбие, возможность атаки и другие состояния юнита не выводятся.",
-- abc3ec81 English: Observe one exact native rune slot using GetRuneType with its single index
--     argument. Require a readable finite positive integral type; known future numeric types remain
--     distinct from the selected type, and Death is an exact type rather than a wildcard. Missing,
--     failed, restricted or malformed observations remain unavailable. No class, unit, count or
--     inferred base-rune query is added.
[2818] = "Наблюдать одну точную встроенную ячейку руны через GetRuneType с единственным аргументом-индексом. Нужен читаемый конечный положительный целый тип; известные будущие числовые типы остаются отличными от выбранного, а «Смерть» — точный тип, а не подстановочный. Отсутствующие, неудачные, ограниченные или повреждённые наблюдения остаются недоступными. Запросы класса, юнита, количества или выведенной базовой руны не добавляются.",
-- 87dc4eea English: Observe one independent zero-argument player flag: stealthed uses IsStealthed,
--     control uses HasFullControl, and outdoors uses IsOutdoors. Readable true and false retain
--     their meanings. Required missing, failed, nil, restricted or malformed data returns nil with
--     a reason. No existence, instance or ability-usability inference is added.
[2819] = "Наблюдать один независимый флаг игрока без аргументов: stealthed — IsStealthed, control — HasFullControl, outdoors — IsOutdoors. Читаемые true и false сохраняют свой смысл. Отсутствующие, неудачные, nil, ограниченные или повреждённые обязательные данные возвращают nil с причиной. Выводы о существовании, подземелье или применимости способностей не добавляются.",
-- 46d51f29 English: Observe one protected zero-argument IsInInstance tuple. Required readable
--     Boolean membership is independent of the type field: known outside returns without
--     interpreting the unused type; inside returns a readable string type or an instanceTypeReason
--     when that secondary field is unavailable. Callers testing outside need only membership;
--     inside type comparisons must check the secondary reason. No outdoors, zone or unit inference
--     is added.
[2820] = "Наблюдать один защищённый кортеж IsInInstance без аргументов. Обязательное читаемое логическое значение нахождения не зависит от поля типа: известное «снаружи» возвращается без разбора неиспользуемого типа; «внутри» возвращает читаемую строку типа или instanceTypeReason, если это вторичное поле недоступно. Проверяющим «снаружи» достаточно факта нахождения; сравнения типа «внутри» должны проверять вторичную причину. Выводы о нахождении под открытым небом, зоне или юните не добавляются.",
-- 5671d2c8 English: Observe ordered selected-unit existence, hostility from player, then the player
--     threat status on that unit. Known absence, nonenemy and a successfully read nil threat status
--     return false, preserving the no-threat predicate. Finite status numbers including zero retain
--     their original comparison meaning. Required missing, failed, nil, restricted or malformed
--     facts return nil with a reason. No attackability, death, combat or vehicle inference is
--     added.
[2821] = "Наблюдать по порядку существование выбранного юнита, враждебность к игроку, затем статус угрозы игрока по этому юниту. Известное отсутствие, не-противник и успешно прочитанный статус угрозы nil возвращают false, сохраняя предикат «нет угрозы». Конечные значения статуса, включая ноль, сохраняют исходный смысл сравнения. Отсутствующие, неудачные, nil, ограниченные или повреждённые обязательные факты возвращают nil с причиной. Выводы о возможности атаки, смерти, бое или транспорте не добавляются.",
-- 545656e0 English: Observe readable current health and optionally maximum health on supported
--     clients. A readable absent unit returns exists=false. Missing, failed, restricted or
--     malformed observations return nil with a reason; they do not establish an absent unit or a
--     health value.
[2822] = "Наблюдать читаемое текущее и, при необходимости, максимальное здоровье на поддерживаемых клиентах. Читаемо отсутствующий юнит возвращает exists=false. Отсутствующие, неудачные, ограниченные или повреждённые наблюдения возвращают nil с причиной; они не означают отсутствия юнита или значения здоровья.",
-- 254b0aeb English: Observe the current player form with one protected zero-argument
--     GetShapeshiftForm call. Preserve every readable finite numeric result, including zero, signed
--     and fractional values; no stronger native index domain is inferred. Missing, failed, nil,
--     restricted or nonfinite data remains unavailable. No form count, class, spell ID, unit or
--     optional argument is added.
[2823] = "Наблюдать текущий облик игрока одним защищённым вызовом GetShapeshiftForm без аргументов. Сохраняется любой читаемый конечный числовой результат, включая ноль, знаковые и дробные значения; более строгая область индексов не выводится. Отсутствующие, неудачные, nil, ограниченные или бесконечные данные остаются недоступными. Число обликов, класс, ID заклинания, юнит или необязательный аргумент не добавляются.",
-- 1de1b681 English: Observe the effective statistic from native return two only. On probe- and
--     restricted-policy clients, query exact UnitExists(unit), then UnitStat(unit,stat) for
--     selector 1..5 or UnitArmor(unit) for selector 6. Known absence returns exists=false; missing,
--     failed, restricted or nonfinite required facts return nil. Preserve finite signed, fractional
--     and zero values; ignore all unused tuple fields. The 1..6 route is an RM selector policy, not
--     a native value-domain limit.
[2824] = "Наблюдать эффективную характеристику только по второму встроенному возвращаемому значению. На клиентах с политикой проверки или ограничения запрашивается точный UnitExists(unit), затем UnitStat(unit,stat) для выбора 1..5 или UnitArmor(unit) для выбора 6. Известное отсутствие возвращает exists=false; отсутствующие, неудачные, ограниченные или бесконечные обязательные факты возвращают nil. Конечные знаковые, дробные и нулевые значения сохраняются; все неиспользуемые поля кортежа игнорируются. Путь 1..6 — правило выбора RM, а не ограничение области встроенных значений.",
-- 2cf23a04 English: Observe the explicitly selected TBC player combo transport. Current uses
--     exactly GetComboPoints(player,target); maximum uses UnitPowerMax(player,powerType) with the
--     original selector. Other families are unavailable here and must use their existing
--     point-power observer. Preserve readable finite signed, fractional and zero values. Missing,
--     failed, restricted or malformed data remains unavailable; a failed chosen combo query never
--     falls back to UnitPower. This observes no other actor and adds no cache.
[2825] = "Наблюдать явно выбранную передачу очков серии игрока в TBC. Для current используется ровно GetComboPoints(player,target); для maximum — UnitPowerMax(player,powerType) с исходным выбором. Другие семейства здесь недоступны и должны использовать свой существующий наблюдатель очков ресурса. Читаемые конечные знаковые, дробные и нулевые значения сохраняются. Отсутствующие, неудачные, ограниченные или повреждённые данные остаются недоступными; неудачный выбранный запрос очков серии никогда не переходит к UnitPower. Другие участники не наблюдаются, кэш не добавляется.",
-- 95b7963d English: Observe the first role result of the exact legacy GetTalentGroupRole(group) dot
--     call on probe- and restricted-policy clients. Forward the readable selected group unchanged,
--     including nil as one argument; do not infer group bounds, substitute another API or query a
--     player unit. The complete legacy primary declaration is not established. Missing, failed,
--     restricted, empty or malformed role data is unavailable; readable nonempty future strings
--     remain exact.
[2826] = "Наблюдать первый результат роли точного старого вызова GetTalentGroupRole(group) через точку на клиентах с политикой проверки или ограничения. Читаемая выбранная группа передаётся без изменений, включая nil как один аргумент; границы группы не выводятся, другой API не подставляется, юнит игрока не запрашивается. Полное старое объявление основной роли не устанавливается. Отсутствующие, неудачные, ограниченные, пустые или повреждённые данные роли недоступны; читаемые непустые будущие строки сохраняются точно.",
-- 79e9c144 English: Observe the first zone PvP classification result with one protected
--     zero-argument dot call. Prefer callable C_PvP.GetZonePVPInfo and use the global helper only
--     when the modern callable is absent. A successful nil or no returned values produces a known
--     empty record; missing, failed, restricted or malformed observations remain unavailable.
--     Readable empty and future strings retain their exact meaning, and unused return fields do not
--     determine availability. Never switch backends after a modern result or failure.
[2827] = "Наблюдать первый результат классификации PvP зоны одним защищённым вызовом через точку без аргументов. Предпочитается вызываемый C_PvP.GetZonePVPInfo, а глобальный помощник используется, только если современного вызова нет. Успешный nil или отсутствие возвращаемых значений дают известную пустую запись; отсутствующие, неудачные, ограниченные или повреждённые наблюдения остаются недоступными. Читаемые пустые и будущие строки сохраняют точный смысл, а неиспользуемые возвращаемые поля не определяют доступность. После результата или ошибки современного варианта переключение на другой никогда не происходит.",
-- 9570ca02 English: Observe the player current movement speed on supported readable clients. This
--     queries GetUnitSpeed for player only, without testing another unit or redirecting vehicle
--     ownership. Zero means stationary; positive finite fractional speeds remain valid. Missing,
--     failed, restricted or malformed observations return nil with a reason.
[2828] = "Наблюдать текущую скорость передвижения игрока на поддерживаемых читаемых клиентах. Запрашивается GetUnitSpeed только для player, без проверки других юнитов и без перенаправления на транспорт. Ноль — стоит на месте; положительные конечные дробные скорости допустимы. Отсутствующие, неудачные, ограниченные или повреждённые наблюдения возвращают nil с причиной.",
-- 6b0f7980 English: Observe unit presence on identified client families. Pass the selected unit
--     unchanged to one protected UnitExists call. Preserve readable true and false; missing,
--     failed, restricted, nil or malformed required observations return nil with a reason. No
--     identity, visibility, range or combat-state query is added.
[2829] = "Наблюдать присутствие юнита на определённых семействах клиентов. Выбранный юнит передаётся без изменений в один защищённый вызов UnitExists. Читаемые true и false сохраняются; отсутствующие, неудачные, ограниченные, nil или повреждённые обязательные наблюдения возвращают nil с причиной. Запросы идентичности, видимости, дальности или боевого состояния не добавляются.",
-- a754c7d3 English: Observe whether the player can attack a selected unit that is not dead, using
--     the exact UnitExists, UnitCanAttack and UnitIsDead predicates. Known absence or a readable
--     false attack result returns false without querying death. Required missing, failed,
--     restricted or malformed observations return nil with a reason. This does not test ghosts,
--     range, hostility or ability usability, and does not redirect unit ownership.
[2830] = "Наблюдать, может ли игрок атаковать выбранный юнит, который не мёртв, с помощью точных предикатов UnitExists, UnitCanAttack и UnitIsDead. Известное отсутствие или читаемый отрицательный результат атаки возвращают false без запроса смерти. Отсутствующие, неудачные, ограниченные или повреждённые обязательные наблюдения возвращают nil с причиной. Призраки, дальность, враждебность и применимость способностей не проверяются, принадлежность юнита не перенаправляется.",
-- d4d5ab66 English: Observed class filename string, false for a known absent unit, or nil when
--     unavailable.
[2831] = "Наблюдаемая строка имени файла класса, false для известного отсутствующего юнита или nil, если недоступно.",
-- 6b236c0f English: Observed membership, or nil when unavailable.
[2832] = "Наблюдаемое членство или nil, если недоступно.",
-- 7c413887 English: On a selected resource only, target-combo for the explicit TBC player fallback
--     or power for the existing selected-unit transport.
[2833] = "Только для выбранного ресурса: target-combo для явного запасного варианта игрока TBC или power для существующей передачи выбранного юнита.",
-- 4b90146b English: On probe- and restricted-policy clients, observe exact UnitExists(unit), then
--     UnitGUID(unit) only for a present unit. Known absence is false. Present identity requires a
--     readable nonempty GUID; missing, failed, malformed or restricted required facts are
--     unavailable. No health, provider or extra-unit observation is added.
[2834] = "На клиентах с политикой проверки или ограничения наблюдать точный UnitExists(unit), затем UnitGUID(unit) только для присутствующего юнита. Известное отсутствие — false. Для идентичности присутствующего юнита нужен читаемый непустой GUID; отсутствующие, неудачные, повреждённые или ограниченные обязательные факты недоступны. Наблюдения здоровья, поставщика или дополнительных юнитов не добавляются.",
-- 7980af82 English: One of class, creature or classification; other metadata kinds are unsupported.
[2835] = "Одно из class, creature или classification; другие виды метаданных не поддерживаются.",
-- f4dbfa56 English: One of combat, enemy or pvp; other flag kinds are not supported.
[2836] = "Одно из combat, enemy или pvp; другие виды флагов не поддерживаются.",
-- 6a9d3fdc English: One of stealthed, control or outdoors; no other predicate is invoked.
[2837] = "Одно из stealthed, control или outdoors; другие предикаты не вызываются.",
-- e7332ebe English: One rounded numeric result from the original formula.
[2838] = "Один округлённый числовой результат по исходной формуле.",
-- ffb1aba4 English: Optional collection of key values selecting entries; its own keys are ignored.
[2839] = "Необязательная коллекция значений-ключей, выбирающих записи; её собственные ключи игнорируются.",
-- a4bd9302 English: Optional ordering callback called as order(t, leftKey, rightKey).
[2840] = "Необязательный обратный вызов порядка, вызываемый как order(t, leftKey, rightKey).",
-- 3a0cafbd English: Optional positive class ID; nil queries the current player class under
--     protection.
[2841] = "Необязательный положительный ID класса; при nil под защитой запрашивается текущий класс игрока.",
-- d8e2dd81 English: Original explicit readable finite nonnegative integer combo-resource selector,
--     including zero; retained for the maximum query.
[2842] = "Исходный явный читаемый конечный неотрицательный целочисленный выбор ресурса очков серии, включая ноль; сохраняется для запроса максимума.",
-- 8311cae8 English: Original non-nil lookup result, or a colored placeholder string.
[2843] = "Исходный результат поиска не nil или цветная строка-заполнитель.",
-- 32680ed5 English: Original non-nil value, or a colored placeholder string.
[2844] = "Исходное значение не nil или цветная строка-заполнитель.",
-- 80842131 English: Original rounded-age bucket count, omitted when the result is the lone zero.
[2845] = "Исходное число интервалов округлённого возраста; опускается, когда результат — одиночный ноль.",
-- 169b03f3 English: Packaged helper from Conditions/spatial.lua.
[2846] = "Поставляемый помощник из Conditions/spatial.lua.",
-- 18a2dc4d English: Packaged helper from utils.lua.
[2847] = "Поставляемый помощник из utils.lua.",
-- dd1476f6 English: Partial current/maximum record, empty when provider absent, or nil when
--     unavailable.
[2848] = "Частичная запись current/maximum; пустая, если поставщика нет; nil, если недоступно.",
-- 52076b9c English: Partial record containing ready or readyReason, start or startReason, and
