[2849] = "Частичная запись с ready или readyReason, start или startReason и duration или durationReason; nil только если сам запрос недоступен.",
-- 7001225d English: Pet observation with Boolean exists and, for a requested present pet, name; nil
--     when required data is unavailable.
[2850] = "Наблюдение питомца с логическим exists и, для запрошенного присутствующего питомца, name; nil, если обязательные данные недоступны.",
-- f4bb093a English: Policy or availability reason for a nil movement observation.
[2851] = "Причина по политике или недоступности для наблюдения движения nil.",
-- 7f7f12b8 English: Policy, capability or clock observation availability reason for a nil time.
[2852] = "Причина недоступности по политике, возможности или наблюдению часов для времени nil.",
-- 43794680 English: Policy, capability or required-observation availability reason.
[2853] = "Причина недоступности по политике, возможности или обязательному наблюдению.",
-- d35012ad English: Policy, query, capability or required row/subject availability reason for a nil
--     record.
[2854] = "Причина недоступности по политике, запросу, возможности или обязательной строке/субъекту для записи nil.",
