[2858] = "Причина по политике, проверке запроса или недоступности для количества nil.",
-- bde90d0c English: Policy, query-validation or availability reason for a nil resource observation.
[2859] = "Причина по политике, проверке запроса или недоступности для наблюдения ресурса nil.",
-- cd1d6bc4 English: Policy, query-validation or availability reason for a nil threat observation.
[2860] = "Причина по политике, проверке запроса или недоступности для наблюдения угрозы nil.",
-- b963fb2b English: Policy, query-validation or availability reason for a nil unit flag.
[2861] = "Причина по политике, проверке запроса или недоступности для флага юнита nil.",
-- de3eca9c English: Policy, query-validation or availability reason for nil attackability.
[2862] = "Причина по политике, проверке запроса или недоступности для возможности атаки nil.",
-- e1be06fc English: Policy, query-validation or identity/selector availability reason for a nil
--     selector.
[2863] = "Причина по политике, проверке запроса или недоступности идентичности/выбора для выбора nil.",
-- a82bb017 English: Policy, query-validation or required observation availability reason for a nil
--     quantity.
[2864] = "Причина по политике, проверке запроса или недоступности обязательного наблюдения для количества nil.",
-- 3422d50e English: Policy, query-validation or required observation availability reason for a nil
--     record.
[2865] = "Причина по политике, проверке запроса или недоступности обязательного наблюдения для записи nil.",
-- 6d8971dd English: Policy, query-validation or required-observation availability reason for a nil
--     ID.
[2866] = "Причина по политике, проверке запроса или недоступности обязательного наблюдения для ID nil.",
-- abb38505 English: Policy, query-validation or required-observation availability reason for a nil
--     match.
[2867] = "Причина по политике, проверке запроса или недоступности обязательного наблюдения для совпадения nil.",
-- 4be03f57 English: Policy, slot-validation or required observation availability reason for a nil
--     type.
[2868] = "Причина по политике, проверке ячейки или недоступности обязательного наблюдения для типа nil.",
-- 07a2f2a4 English: Policy, slot-validation, capability or native-call availability reason for a
--     nil record.
[2869] = "Причина по политике, проверке ячейки, возможности или недоступности встроенного вызова для записи nil.",
-- 57d4e2a6 English: Policy, snapshot, identity or threat observation availability reason.
[2870] = "Причина недоступности по политике, снимку, идентичности или наблюдению угрозы.",
-- 88172c69 English: Policy, token-validation or availability reason for a nil identity result.
[2871] = "Причина по политике, проверке токена или недоступности для результата идентичности nil.",
-- 41f7dc66 English: Policy, validation or availability reason for a nil health observation.
[2872] = "Причина по политике, проверке или недоступности для наблюдения здоровья nil.",
-- cc67968e English: Policy, validation or availability reason for a nil snapshot.
[2873] = "Причина по политике, проверке или недоступности для снимка nil.",
-- 84bacc88 English: Policy, validation or observation availability reason.
[2874] = "Причина по политике, проверке или недоступности наблюдения.",
-- 702b5d1d English: Policy, validation or required observation availability reason.
[2875] = "Причина по политике, проверке или недоступности обязательного наблюдения.",
-- e3a0a3ce English: Positive integer glyph item ID stored by the condition; arrays, item-set keys
--     and spell IDs are not item references.
[2876] = "Положительный целый ID предмета-символа, сохранённый условием; массивы, ключи комплектов и ID заклинаний не являются ссылками на предметы.",
-- c7e5f035 English: Positive integer level, false for a known absent unit, or nil when unavailable.
[2877] = "Положительный целый уровень, false для известного отсутствующего юнита или nil, если недоступно.",
-- 2ce665d6 English: Positive integer spell ID, not a spell-book slot.
[2878] = "Положительный целый ID заклинания, а не ячейка книги заклинаний.",
-- 37be242f English: Positive item ID or native-recognized item name/link to classify.
[2879] = "Положительный ID предмета или распознаваемые игрой название/ссылка предмета для классификации.",
-- eac23024 English: Predicate that validates the proposed spell value.
[2880] = "Предикат, проверяющий предлагаемое значение заклинания.",
-- b7acadb2 English: Present GUID, false for known absence, or nil when unavailable.
[2881] = "GUID присутствующего юнита, false при известном отсутствии или nil, если недоступно.",
-- 5825055c English: Provider, validation or observation availability reason.
[2882] = "Причина недоступности по поставщику, проверке или наблюдению.",
-- e78c7309 English: Query, policy or observation availability reason.
[2883] = "Причина недоступности по запросу, политике или наблюдению.",
-- b79b336b English: RM comparison operator identifier; missing labels use the operator placeholder.
[2884] = "Идентификатор оператора сравнения RM; для отсутствующих подписей используется заполнитель оператора.",
-- 505c9dde English: RM operator identifier.
[2885] = "Идентификатор оператора RM.",
-- a3bcccb3 English: Range record with applicable and, when applicable, inRange; nil when
--     unavailable.
[2886] = "Запись дальности с applicable и, если применимо, inRange; nil, если недоступно.",
-- a18d0c99 English: Read a fresh protected UnitClass player observation for rotation ownership.
--     Consume only the readable nonempty class filename from return two. No existence, level,
--     vehicle, family or combat-policy read is added, and no result persists across calls. Core
--     ownership still validates the class token and character key separately; overridden context
--     providers retain their complete original path.
[2887] = "Прочитать свежее защищённое наблюдение UnitClass для player, чтобы определить владельца ротации. Используется только читаемое непустое имя файла класса из второго возвращаемого значения. Чтения существования, уровня, транспорта, семейства или боевой политики не добавляются, и результат не сохраняется между вызовами. Ядро по-прежнему отдельно проверяет токен класса и ключ персонажа; переопределённые поставщики контекста сохраняют свой полный исходный путь.",
-- 97b3a051 English: Read a fresh protected zero-argument GetTime for rune cooldown arithmetic.
--     Require a readable finite number. This observation is deliberately uncached; callers preserve
--     the original clock-before-scan order and require its value only when a matching rune needs
--     timing. No evaluation-start substitution or inferred time is supplied.
[2888] = "Прочитать свежее значение защищённого GetTime без аргументов для расчёта восстановления рун. Требуется читаемое конечное число. Это наблюдение намеренно не кэшируется; вызывающие сохраняют исходный порядок «часы перед сканированием» и требуют значение только тогда, когда подходящей руне нужен расчёт времени. Подстановка времени начала вычисления или выведенное время не используются.",
-- 3b2652a8 English: Read a lazy health scalar after a separate identity gate. Kind current uses
--     exact UnitHealth(unit); maximum uses exact UnitHealthMax(unit). Probe- and restricted-policy
--     clients accept readable finite nonnegative numbers including zero. No repeated existence/GUID
--     call or alternate tuple fallback is added.
[2889] = "Прочитать ленивое скалярное значение здоровья после отдельной проверки идентичности. Вид current использует точный UnitHealth(unit), maximum — точный UnitHealthMax(unit). Клиенты с политикой проверки или ограничения принимают читаемые конечные неотрицательные числа, включая ноль. Повторный вызов существования/GUID или запасной кортеж не добавляются.",
-- cd858e26 English: Read a normalized charge record: currentCharges, maxCharges, cooldownStartTime,
--     cooldownDuration, chargeModRate and isActive. Unsupported spells or restricted client data
--     return nil with a reason.
[2890] = "Прочитать нормализованную запись зарядов: currentCharges, maxCharges, cooldownStartTime, cooldownDuration, chargeModRate и isActive. Для неподдерживаемых заклинаний или ограниченных данных клиента возвращается nil с причиной.",
-- 3ba4fbdf English: Read a specified unit membership in the player party or raid. True raidOnly
--     queries only UnitInRaid; otherwise a true UnitInParty result short-circuits, false proceeds
--     to UnitInRaid, and unknown remains unavailable. Readable nil raid index means false; integer
--     raid index1..40 means true. Names are passed unchanged to native APIs; native name-query
--     acceptance requires client qualification.
[2891] = "Прочитать членство указанного юнита в группе или рейде игрока. При raidOnly true запрашивается только UnitInRaid; иначе результат true от UnitInParty завершает проверку, false переходит к UnitInRaid, а неизвестный остаётся недоступным. Читаемый индекс рейда nil означает false; целый индекс рейда 1..40 — true. Имена передаются встроенным API без изменений; приём имён встроенным запросом зависит от квалификации клиента.",
-- 3db7feb7 English: Read and normalize a spell cooldown across supported clients. The returned
--     record contains startTime, duration, isEnabled and modRate. The timestamps and duration
--     already describe expiration in GetTime() seconds; do not divide them by modRate. When the
--     client hides the times (Retail and Forever in combat) the record is nil with reason
--     restricted-value, followed by the never-secret isEnabled, isActive and isOnGCD flags when
--     they can be read.
[2892] = "Считывает и нормализует время восстановления заклинания во всех поддерживаемых клиентах. Возвращаемая запись содержит startTime, duration, isEnabled и modRate. Метки времени и длительность уже описывают окончание в секундах GetTime(); не делите их на modRate. Когда клиент скрывает время (Retail и Forever в бою), запись равна nil с причиной restricted-value, а за ней следуют никогда не скрываемые флаги isEnabled, isActive и isOnGCD, если их удаётся прочитать.",
-- 4ae0aa42 English: Read normalized native item classification metadata. The record contains
--     canonical itemID, classID and subClassID, plus equipLoc, the non-localized INVTYPE_* equip
--     location token, when it is readable and nonempty; it does not require loaded item display
--     text. Missing, failed, malformed or restricted metadata returns nil with a reason.
[2893] = "Прочитать нормализованные встроенные метаданные классификации предмета. Запись содержит канонические itemID, classID и subClassID, а также equipLoc — нелокализованный токен места экипировки INVTYPE_*, если он читаем и не пуст; загруженный отображаемый текст предмета не требуется. Отсутствующие, неудачные, некорректные или ограниченные метаданные возвращают nil с причиной.",
-- 5286a3fe English: Read one documented active loss-of-control row by its native index and
--     requested subject kind. Type queries require only the readable control type string; school
--     queries require only the readable finite nonnegative integer school mask. Optional timing is
--     returned as a finite timeRemaining or an explicit per-field reason, so an unrelated subject
--     does not require a usable timer. Missing rows are unavailable snapshot observations. No
--     display fields, inferred deadline, duration sum, maximum or native alias fallback is used.
[2894] = "Прочитать одну документированную строку активной потери контроля по её встроенному индексу и запрошенному виду субъекта. Запросы типа требуют только читаемой строки типа контроля; запросы школы — только читаемой конечной неотрицательной целой маски школы. Необязательное время возвращается как конечное timeRemaining или явная причина для поля, поэтому для постороннего субъекта рабочий таймер не нужен. Отсутствующие строки — недоступные наблюдения снимка. Поля отображения, выведенный срок, сумма длительностей, максимум или запасные встроенные псевдонимы не используются.",
-- 5a423c22 English: Read one explicitly selected point-resource quantity with an exact two-argument
--     UnitPower or UnitPowerMax query. The selector is required; no primary-resource inference or
--     actor remapping occurs. Preserve finite signed, fractional and zero quantities without
--     clamping. Missing, failed, restricted or nonfinite data remains unavailable. Current and
--     maximum are separate observations so callers can share current snapshots while requesting
--     maximum lazily.
[2895] = "Прочитать одно явно выбранное количество очков ресурса точным запросом UnitPower или UnitPowerMax с двумя аргументами. Выбор обязателен; основной ресурс не выводится, участники не переназначаются. Конечные знаковые, дробные и нулевые количества сохраняются без усечения. Отсутствующие, неудачные, ограниченные или бесконечные данные остаются недоступными. Current и maximum — отдельные наблюдения, чтобы вызывающие могли делиться снимками текущего значения, запрашивая максимум лениво.",
-- 9f37d74c English: Read one protected GetRuneCooldown tuple for an exact native slot. Normalize
--     ready, start and duration independently: ready requires a readable Boolean, while each time
--     requires a readable finite number and preserves signed, fractional and zero values. Every
--     unavailable field carries its own reason. A successful empty tuple yields a partial record;
--     missing capability, policy or native-call failure yields nil. Never infer ready from timing
--     or timing from ready. Cache this complete record at the caller to share one observation
--     between rune-count and cooldown predicates.
[2896] = "Прочитать один защищённый кортеж GetRuneCooldown для точной встроенной ячейки. ready, start и duration нормализуются независимо: для ready нужен читаемый логический тип, для каждого времени — читаемое конечное число с сохранением знаковых, дробных и нулевых значений. У каждого недоступного поля своя причина. Успешный пустой кортеж даёт частичную запись; отсутствие возможности, политика или сбой встроенного вызова дают nil. ready никогда не выводится из времени, а время — из ready. Кэшируйте эту полную запись у вызывающего, чтобы одно наблюдение разделялось предикатами числа рун и восстановления.",
-- 0ab0e9af English: Read optional MobInfo2 historical observations on probe- and restricted-policy
--     clients. Cache only exact selected-unit presence; UnitName result one, UnitLevel result one
--     and the three-argument MI2_GetMobData(name,level,unit) dot call stay fresh each invocation.
--     Known absent units and successful unrecorded nil or omitted history remain distinct from
--     unavailable native/provider facts. Preserve readable runner scalar truthiness, school signs
--     and missing-Hits default one. Positive resistance ratios must be finite; complete immunity
--     consumes finite Hits while partial immunity needs only its negative school observation. Never
--     infer native resistance or borrow old records.
[2897] = "Прочитать необязательные исторические наблюдения MobInfo2 на клиентах с политикой проверки или ограничения. Кэшируется только точное присутствие выбранного юнита; первый результат UnitName, первый результат UnitLevel и вызов через точку MI2_GetMobData(name,level,unit) с тремя аргументами остаются свежими при каждом вызове. Известно отсутствующие юниты и успешные незаписанные nil или опущенная история отличаются от недоступных встроенных фактов и фактов поставщика. Сохраняются читаемая истинность скаляра runner, знаки школ и значение по умолчанию 1 для отсутствующего Hits. Положительные коэффициенты сопротивления должны быть конечными; полная невосприимчивость использует конечный Hits, а частичной нужна только отрицательная запись школы. Встроенное сопротивление никогда не выводится, старые записи не заимствуются.",
-- a27fc0e3 English: Read optional RealMobHealth using its exact one-argument dot call. Absent
--     nil/false namespace returns an empty record. Normalize current and maximum independently:
--     nil/false fields permit native fallback, numeric zero remains present. Malformed, failed,
--     restricted, negative or nonfinite consumed provider facts are unavailable. No provider or
--     stale fallback cache is used.
[2898] = "Прочитать необязательный RealMobHealth точным вызовом через точку с одним аргументом. Отсутствующее (nil/false) пространство имён возвращает пустую запись. current и maximum нормализуются независимо: поля nil/false разрешают встроенный запасной вариант, числовой ноль считается присутствующим. Повреждённые, неудачные, ограниченные, отрицательные или бесконечные используемые факты поставщика недоступны. Кэш поставщика или устаревших значений не используется.",
-- 0a7395cc English: Read public group membership on identified client families. Unknown clients are
--     unsupported. True raidOnly checks IsInRaid; false or nil checks IsInGroup using its native
--     default group category. A readable false result stays false. Missing, failed, malformed or
--     restricted observations return nil with a reason.
[2899] = "Прочитать общедоступное членство в группе на определённых семействах клиентов. Неизвестные клиенты не поддерживаются. При raidOnly true проверяется IsInRaid; при false или nil — IsInGroup с его встроенной категорией группы по умолчанию. Читаемый результат false остаётся false. Отсутствующие, неудачные, повреждённые или ограниченные наблюдения возвращают nil с причиной.",
-- 4a264ad3 English: Read public roster identity on identified client families. Input routing is
--     limited to player, party1 through party4 and raid1 through raid40. Call UnitExists with that
--     exact one-argument token first; known false returns false without querying class. For a
--     present unit, consume only UnitClass return two as a readable nonempty class filename string,
--     without a class enum restriction. Missing, failed, malformed or restricted required facts
--     return nil with a reason.
[2900] = "Прочитать общедоступную идентичность состава на определённых семействах клиентов. Входные токены ограничены player, party1–party4 и raid1–raid40. Сначала вызывается UnitExists с этим точным токеном; известное false возвращает false без запроса класса. Для присутствующего юнита используется только второе возвращаемое значение UnitClass как читаемая непустая строка имени файла класса, без ограничения перечислением классов. Отсутствующие, неудачные, повреждённые или ограниченные обязательные факты возвращают nil с причиной.",
-- 1f3c0a57 English: Read spell-specific range for a unit using the appropriate client API or
--     spell-book slot. A spell without a range restriction returns applicable=false; otherwise
--     applicable=true and inRange records whether the unit is in range. Unknown or inaccessible
--     observations return nil with a reason.
[2901] = "Прочитать дальность конкретного заклинания для юнита через подходящий API клиента или ячейку книги заклинаний. Заклинание без ограничения дальности возвращает applicable=false; иначе applicable=true, а inRange сообщает, находится ли юнит в зоне досягаемости. Неизвестные или недоступные наблюдения возвращают nil с причиной.",
-- d3d07abb English: Read the current positive nameplate visibility distance using the supported
--     CVar API. This limits a Distance Count query; it does not prove that all nearby units have
--     been observed. Missing, malformed, restricted or failed observations return nil with a
--     reason.
[2902] = "Прочитать текущую положительную дальность видимости индикаторов здоровья через поддерживаемый API CVar. Это ограничивает запрос «Число в радиусе»; это не доказывает, что все ближайшие юниты наблюдались. Отсутствующие, повреждённые, ограниченные или неудачные наблюдения возвращают nil с причиной.",
-- f4bc8da4 English: Read the documented active loss-of-control count with a protected zero-argument
--     dot call. Require a readable finite nonnegative integer. Zero is a complete empty scan and
--     does not require a row API. RM limits a scan to 256 rows and returns unavailable beyond that
--     resource budget; this is not a declared native maximum. Required missing, failed, restricted
--     or malformed observations remain unavailable.
[2903] = "Прочитать документированное число активных потерь контроля защищённым вызовом через точку без аргументов. Требуется читаемое конечное неотрицательное целое. Ноль — полное пустое сканирование, API строк не требуется. RM ограничивает сканирование 256 строками и сверх этого бюджета возвращает «недоступно»; это не заявленный встроенный максимум. Отсутствующие, неудачные, ограниченные или повреждённые обязательные наблюдения остаются недоступными.",
-- 597a72b9 English: Read the player auto-repeat state for a spell such as Shoot or Auto Shot. This
--     is distinct from a current or queued cast. Modern clients receive the exact spell ID; a
--     legacy query resolves the player spell-book slot first. Restricted client policies,
--     unreadable results and unavailable book slots return nil with a reason. This observes state
--     and never starts or stops a spell.
[2904] = "Прочитать состояние автоповтора игрока для заклинания вроде «Выстрела» или «Автоматической стрельбы». Это не то же, что текущее или поставленное в очередь применение. Современные клиенты получают точный ID заклинания; старый запрос сначала определяет ячейку книги заклинаний игрока. Ограничения политики клиента, нечитаемые результаты и недоступные ячейки книги возвращают nil с причиной. Только наблюдается состояние; заклинание никогда не запускается и не останавливается.",
-- 89759fd9 English: Read the public LibRangeCheck interval for a unit. A successful upper bound is
--     inclusive; a positive failed lower bound is strict. A zero lower floor is synthetic. Neither
--     bound is an exact distance, and a missing upper bound is not proof that the unit is outside
--     every radius. Unavailable, malformed, restricted or failed observations return nil with a
--     reason.
[2905] = "Прочитать общедоступный интервал LibRangeCheck для юнита. Успешная верхняя граница включительна; положительная неудачная нижняя граница строгая. Нулевая нижняя граница искусственная. Ни одна граница не является точным расстоянием, а отсутствие верхней границы не доказывает, что юнит вне любого радиуса. Недоступные, повреждённые, ограниченные или неудачные наблюдения возвращают nil с причиной.",
-- 41e0213a English: Readability authority for consumed values.
[2906] = "Источник проверки читаемости используемых значений.",
-- 7f7e5283 English: Readable canonical item classification record (itemID, classID, subClassID and
--     optional equipLoc), or nil when unavailable.
[2907] = "Читаемая каноническая запись классификации предмета (itemID, classID, subClassID и необязательный equipLoc) или nil, если недоступна.",
-- 708f11a6 English: Readable canonical itemID/classID/subClassID record when the item is a glyph
--     for the requested class; nil for invalid or unavailable metadata.
[2908] = "Читаемая каноническая запись itemID/classID/subClassID, если предмет — символ для запрошенного класса; nil для некорректных или недоступных метаданных.",
-- b7b27422 English: Readable charge record, or nil when unavailable.
[2909] = "Читаемая запись зарядов или nil, если недоступно.",
-- 5274b7b7 English: Readable consumed metadata string, false for a known absent unit, or nil when
--     required data is unavailable.
[2910] = "Читаемая используемая строка метаданных, false для известного отсутствующего юнита или nil, если обязательные данные недоступны.",
-- 041c7f05 English: Readable cooldown record, or nil when unavailable.
[2911] = "Читаемая запись восстановления или nil, если недоступно.",
-- c171ab16 English: Readable current state, or nil when unavailable.
[2912] = "Читаемое текущее состояние или nil, если недоступно.",
-- ea709ff8 English: Readable finite current-form observation, including zero for the current
--     unshifted comparison; nil when unavailable.
[2913] = "Читаемое конечное наблюдение текущего облика, включая ноль для сравнения «без облика»; nil, если недоступно.",
-- 5fe2cef3 English: Readable finite positive integral rune type, or nil when unavailable.
[2914] = "Читаемый конечный положительный целый тип руны или nil, если недоступно.",
-- 243ee644 English: Readable interval with optional minimum and maximum bounds in yards. At least
--     one bound is present; nil when unavailable.
[2915] = "Читаемый интервал с необязательными нижней и верхней границами в метрах. Есть хотя бы одна граница; nil, если недоступно.",
-- 7c9763dd English: Readable nonempty selected unit token, passed unchanged as the single argument
--     to existence and creature metadata queries.
[2916] = "Читаемый непустой токен выбранного юнита, передаваемый без изменений единственным аргументом в запросы существования и метаданных существа.",
-- 2ce03ebb English: Readable nonempty unit token or native-recognized name, passed unchanged.
[2917] = "Читаемый непустой токен юнита или распознаваемое игрой имя, передаётся без изменений.",
-- 30a14f21 English: Readable nonempty unit token to match, unchanged in the native observation.
[2918] = "Читаемый непустой токен юнита для сопоставления, без изменений во встроенном наблюдении.",
-- 4421ce67 English: Readable nonempty unit token, passed unchanged as the single native argument.
[2919] = "Читаемый непустой токен юнита, передаваемый без изменений единственным встроенным аргументом.",
-- 831ff884 English: Readable record with Boolean exists and the requested class filename when
--     present; nil when required data is unavailable.
[2920] = "Читаемая запись с логическим exists и, если юнит есть, запрошенным именем файла класса; nil, если обязательные данные недоступны.",
-- e5d5a0bd English: Readable selected flag or nil when required data is unavailable.
[2921] = "Читаемый выбранный флаг или nil, если обязательные данные недоступны.",
-- ae99174e English: Readable selected flag, false for a known absent unit, or nil when a required
--     observation is unavailable.
[2922] = "Читаемый выбранный флаг, false для известного отсутствующего юнита или nil, если обязательное наблюдение недоступно.",
-- 15d71981 English: Readable unit equality, false for a known absent first unit, or nil when
--     required observations are unavailable.
[2923] = "Читаемое равенство юнитов, false для известного отсутствующего первого юнита или nil, если обязательные наблюдения недоступны.",
-- c72ce8bc English: Record with exists=false, or exists=true and finite value; nil when
--     unavailable.
[2924] = "Запись с exists=false или exists=true и конечным value; nil, если недоступно.",
-- bbdbf34c English: Record with exists=false; recorded=false for known no history; or runner,
--     ratio, or immune with hits/hitsReason. Nil means a required observation is unavailable.
[2925] = "Запись с exists=false; recorded=false при известном отсутствии истории; либо runner, ratio или immune с hits/hitsReason. nil означает, что обязательное наблюдение недоступно.",
-- d2443dc7 English: Record with inInstance and, when inside, instanceType or instanceTypeReason;
--     nil when membership is unavailable.
[2926] = "Запись с inInstance и, если внутри, instanceType или instanceTypeReason; nil, если нахождение недоступно.",
-- b2c4007b English: Reference input kind, such as Spec_EditBox, used for spell suggestions.
[2927] = "Вид входного элемента-образца, например Spec_EditBox, используемый для подсказок заклинаний.",
-- 27542d97 English: Remove entries in place, preserving only keys listed among except values by
--     default. With invert true, remove listed keys and retain unlisted keys. Without an exception
--     list, the default removes every entry and invert true retains every entry. Nil input does
--     nothing.
[2928] = "Удалить записи на месте, по умолчанию оставляя только ключи, перечисленные в значениях except. При invert true перечисленные ключи удаляются, а неперечисленные остаются. Без списка исключений по умолчанию удаляются все записи, а при invert true все сохраняются. При входе nil ничего не происходит.",
-- e6ab096c English: Remove leading and trailing Lua-pattern whitespace from a string.
[2929] = "Удалить начальные и конечные пробельные символы (по шаблону Lua) из строки.",
-- a3fc9f6e English: Resolve a readable raw unit level for condition evaluation. Known absence
--     returns false; unavailable observations return nil with a reason. Cache observations within
--     the supplied evaluation pass. Only valid player levels are retained between passes until a
--     skill, profile or level refresh.
[2930] = "Определить читаемый исходный уровень юнита для вычисления условия. Известное отсутствие возвращает false; недоступные наблюдения возвращают nil с причиной. Наблюдения кэшируются в пределах переданного прохода вычисления. Между проходами сохраняются только корректные уровни игрока — до обновления навыка, профиля или уровня.",
-- 1be3efe7 English: Resolve an exact cast-recipient name against the current bounded party or raid
--     roster, then observe membership through a unit token. Missing, ambiguous or changing roster
--     data remains unavailable; never reads the selected target or retains state across casts.
[2931] = "Сопоставить точное имя получателя применения с текущим ограниченным составом группы или рейда, затем наблюдать членство через токен юнита. Отсутствующие, неоднозначные или меняющиеся данные состава остаются недоступными; выбранная цель никогда не читается, состояние между применениями не сохраняется.",
-- bf87a408 English: Resolve point resources using the original live class mapping and identity
--     cache, with an explicit TBC player ComboPoints-fallback transport policy. A player fallback
--     matching the readable raw Enum.PowerType table and ComboPoints value captured at module load
--     selects target-combo; explicit class-map entries, other actors and other families retain
--     power. Replaced, inherited or unprovable fallback provenance retains power. This versioned
--     policy does not claim native UnitPower is broken or equivalent. Known unit absence returns
--     false; unavailable required observations return nil with a reason. No current or maximum
--     quantity is queried here.
[2932] = "Определить очки ресурса по исходному действующему соответствию классов и кэшу идентичности, с явной политикой передачи для запасного варианта ComboPoints игрока TBC. Запасной вариант игрока, совпадающий с читаемой исходной таблицей Enum.PowerType и значением ComboPoints, захваченными при загрузке модуля, выбирает target-combo; явные записи таблицы классов, другие участники и другие семейства сохраняют power. Заменённое, унаследованное или недоказуемое происхождение запасного варианта сохраняет power. Эта версионированная политика не утверждает, что встроенный UnitPower сломан или эквивалентен. Известное отсутствие юнита возвращает false; недоступные обязательные наблюдения возвращают nil с причиной. Текущее или максимальное количество здесь не запрашивается.",
-- b9173e02 English: Resolve the selected unit point-resource selector using the live
--     class-to-resource map and ComboPoints fallback. Known absence returns false; unavailable
--     required identity or selector data returns nil with a reason. Share complete identity
--     observations within the evaluation pass. Only successful player class observations persist in
--     the current longterm cache, tied to the native UnitClass identity; existence is refreshed
--     each pass. This selects a resource without reading its current or maximum quantity.
[2933] = "Определить выбор очков ресурса выбранного юнита по действующей таблице «класс — ресурс» и запасному варианту ComboPoints. Известное отсутствие возвращает false; недоступные обязательные данные идентичности или выбора возвращают nil с причиной. Полные наблюдения идентичности разделяются в пределах прохода вычисления. В текущем долговременном кэше, привязанном к встроенной идентичности UnitClass, сохраняются только успешные наблюдения класса игрока; существование обновляется при каждом проходе. Ресурс выбирается без чтения его текущего или максимального количества.",
-- 718644e5 English: Resolve the spell identifier stored by a condition. With exact rank enabled the
--     supplied ID is retained; otherwise ranked Classic clients resolve the currently known rank
--     through the spell catalog. Returns nil and an availability reason if resolution cannot be
--     completed.
[2934] = "Определить идентификатор заклинания, сохранённый условием. При включённом точном ранге переданный ID сохраняется; иначе клиенты Classic с рангами определяют текущий известный ранг через каталог заклинаний. Если определить не удаётся, возвращаются nil и причина недоступности.",
-- 1d0d55d1 English: Resolved spell ID, or nil when unavailable.
[2935] = "Определённый ID заклинания или nil, если недоступно.",
-- 6ffafa71 English: Resolver mapping a typed spell name to its ID.
[2936] = "Сопоставитель набранного названия заклинания и его ID.",
-- 09cbb92e English: Return a present value unchanged, or a red display placeholder for nil. Use for
--     readable condition labels, not as a boolean fallback.
[2937] = "Вернуть присутствующее значение без изменений или красный заполнитель для nil. Используйте для читаемых подписей условий, а не как логический запасной вариант.",
-- d42a9ff5 English: Return the first key whose value equals the supplied value during pairs
--     traversal. Nil or false input tables and absent values return nil. Multiple matching keys
--     have no guaranteed selection order.
[2938] = "Вернуть первый ключ, значение которого равно переданному, при обходе pairs. Для таблиц nil или false и отсутствующих значений возвращается nil. При нескольких совпадающих ключах порядок выбора не гарантирован.",
-- 3f5f3e62 English: Right operand; DIVISIBLE requires a nonzero divisor.
[2939] = "Правый операнд; для DIVISIBLE нужен ненулевой делитель.",
-- 6734885b English: Rotation Master addon instance (implicit with colon calls).
[2940] = "Экземпляр аддона Rotation Master (неявно при вызове через двоеточие).",
-- 46daa133 English: Rotation Master platform adapter (implicit with colon calls).
[2941] = "Адаптер платформы Rotation Master (неявно при вызове через двоеточие).",
-- f0f9c415 English: Rotation Master platform adapter. A dot reference requires addon.Platform as
--     the first argument; a colon call supplies it implicitly.
[2942] = "Адаптер платформы Rotation Master. При обращении через точку первым аргументом нужен addon.Platform; при вызове через двоеточие он передаётся неявно.",
-- 3f1284ef English: Round with the existing floor(num * 10^places + 0.5) / 10^places formula.
--     Places defaults to zero and may be negative. Halfway negative values round toward positive
--     infinity; no finite-number validation or alternative rounding policy is added.
[2943] = "Округлить по существующей формуле floor(num * 10^places + 0.5) / 10^places. По умолчанию places равно нулю и может быть отрицательным. Отрицательные значения ровно посередине округляются в сторону плюс бесконечности; проверка конечности или другая политика округления не добавляются.",
-- 885bcca4 English: Run the historical health-snapshot trend formula using the live profile history
--     window, clock and legacy rounding service. Preserve its maximum-health transitions, early
--     stop at full or zero health, weighting, errors and return counts. An empty array, or
--     snapshots that record no weighted change, return only zero rather than a 0/0 result; this is
--     the legacy algorithm rather than a validated forecast.
